                  {p.recu && (
                    <button onClick={() => telechargerRecu(p)} disabled={telechargement === p.id} className="tap" style={{ flex: 1, backgroundColor: "rgba(245,166,35,0.1)", border: "1px solid rgba(245,166,35,0.3)", color: "#F5A623", fontWeight: 700, fontSize: "12.5px", padding: "10px", borderRadius: "10px", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", gap: "6px" }}>
