              {secteur && (
                <span style={{ backgroundColor: `${C.gold}12`, border: `1px solid ${C.gold}30`, color: C.gold, fontSize: "11px", fontWeight: "700", padding: "5px 11px", borderRadius: "20px" }}>{SECTEUR_LABEL_BY_ID[secteur] || secteur}</span>
