                  </div>
                  <div style={{ paddingBottom: "12px" }}>
                    <div style={{ color: C.t1, fontSize: "12.5px", fontWeight: "700" }}>{etape.label}</div>
                    <div style={{ color: C.t3, fontSize: "11px", marginTop: "1px" }}>{formatDateHeure(etape.date)}</div>
                  </div>
