              <span style={{ color: C.t3, fontSize: "12px", width: "60px", flexShrink: 0, paddingTop: "1px" }}>{item.label}</span>
              <span style={{ color: C.t1, fontSize: "13px", fontWeight: "700", flex: 1 }}>{item.value}</span>
