                  borderRadius: isNouveau ? "22px" : "20px",
                  padding: isNouveau ? "10px 18px" : "6px 12px",
                  color: active ? (isGoldFilter ? "#000" : sc.c) : (isNouveau ? sc.c : C.t2),
                  fontSize: isNouveau ? "13px" : "11px",
                  fontWeight: isNouveau ? "900" : (active ? "800" : "600"),
