                  style={{ flex: 1, padding: "10px 4px", background: "#fffbef", color: "#c8972a", border: "none", borderRadius: 9, fontSize: 12, fontWeight: 700, cursor: "pointer" }}>
                  Copier URL
                </button>
              </div>
            </div>
          </div>
