"use client";

import { supabase } from "@/lib/supabase";
import { useRouter } from "next/navigation";
import { useCallback, useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { useTheme } from "@/components/ThemeProvider";
import { ThemeToggle } from "@/components/ThemeToggle";
import { YelenLoader } from "@/components/YelenLoader";

// ─── Types ────────────────────────────────────────────────────────────────────

type DayKey = "lundi" | "mardi" | "mercredi" | "jeudi" | "vendredi" | "samedi" | "dimanche";
type DayRule = { active: boolean; start: string; end: string; duration: 15 | 30 | 45 | 60 };

const DAYS: Array<{ key: DayKey; label: string; abbrev: string; icon: string }> = [
  { key: "lundi",    label: "Lundi",    abbrev: "Lun", icon: "1" },
  { key: "mardi",    label: "Mardi",    abbrev: "Mar", icon: "2" },
  { key: "mercredi", label: "Mercredi", abbrev: "Mer", icon: "3" },
  { key: "jeudi",    label: "Jeudi",    abbrev: "Jeu", icon: "4" },
  { key: "vendredi", label: "Vendredi", abbrev: "Ven", icon: "5" },
  { key: "samedi",   label: "Samedi",   abbrev: "Sam", icon: "6" },
  { key: "dimanche", label: "Dimanche", abbrev: "Dim", icon: "7" },
];

const DURATIONS: Array<DayRule["duration"]> = [15, 30, 45, 60];

// ─── Helpers ──────────────────────────────────────────────────────────────────

function toMin(v: string): number | null {
  const m = /^(\d{2}):(\d{2})$/.exec(v.trim());
  if (!m) return null;
  const h = Number(m[1]), mm = Number(m[2]);
  if (h < 0 || h > 23 || mm < 0 || mm > 59) return null;
  return h * 60 + mm;
}

function toHHMM(t: number): string {
  return `${String(Math.floor(t / 60)).padStart(2, "0")}:${String(t % 60).padStart(2, "0")}`;
}

function emptyRules(): Record<DayKey, DayRule> {
  return DAYS.reduce((a, d) => ({ ...a, [d.key]: { active: false, start: "", end: "", duration: 30 } }), {} as Record<DayKey, DayRule>);
}

function parseToRules(raw: unknown): Record<DayKey, DayRule> {
  const rules = emptyRules();
  let list: unknown = raw;
  if (typeof raw === "string") { try { list = JSON.parse(raw); } catch { return rules; } }
  if (!Array.isArray(list)) return rules;

  const byDay: Partial<Record<DayKey, number[]>> = {};
  for (const item of list) {
    if (typeof item !== "string") continue;
    const m = /^([A-Za-z]{3})\s+(\d{2}:\d{2})$/.exec(item.trim());
    if (!m) continue;
    const mins = toMin(m[2]);
    if (mins === null) continue;
    const day = DAYS.find(d => d.abbrev.toLowerCase() === m[1].toLowerCase())?.key;
    if (!day) continue;
    byDay[day] = [...(byDay[day] ?? []), mins];
  }

  for (const d of DAYS) {
    const times = (byDay[d.key] ?? []).sort((a, b) => a - b);
    if (!times.length) continue;
    const deltas = times.slice(1).map((t, i) => t - times[i]).filter(t => [15,30,45,60].includes(t));
    const freq = deltas.reduce((a, v) => { a[v] = (a[v] ?? 0) + 1; return a; }, {} as Record<number, number>);
    const dur = (Number(Object.entries(freq).sort((a, b) => b[1] - a[1])[0]?.[0] ?? 30)) as DayRule["duration"];
    rules[d.key] = { active: true, start: toHHMM(times[0]), end: toHHMM(times[times.length - 1] + dur), duration: Number(dur) as DayRule["duration"] };
  }
  return rules;
}

function generateSlots(rules: Record<DayKey, DayRule>): string[] {
  const slots: string[] = [];
  for (const d of DAYS) {
    const r = rules[d.key];
    if (!r.active) continue;
    const s = toMin(r.start), e = toMin(r.end);
    if (s === null || e === null || e <= s) continue;
    for (let t = s; t + r.duration <= e; t += r.duration) slots.push(`${d.abbrev} ${toHHMM(t)}`);
  }
  return [...new Set(slots)].sort((a, b) => a.localeCompare(b));
}

function countSlots(rules: Record<DayKey, DayRule>, key: DayKey): number {
  const r = rules[key];
  if (!r.active) return 0;
  const s = toMin(r.start), e = toMin(r.end);
  if (s === null || e === null || e <= s) return 0;
  return Math.floor((e - s) / r.duration);
}

// ─── Page ─────────────────────────────────────────────────────────────────────

export default function InstitutionDisponibilitesPage() {
  const router = useRouter();
  const { theme } = useTheme();
  const isDark = theme === "dark";

  const [institutionId, setInstitutionId] = useState<string | null>(null);
  const [institutionName, setInstitutionName] = useState("");
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [rules, setRules] = useState<Record<DayKey, DayRule>>(emptyRules());
  const [saving, setSaving] = useState(false);
  const [saveMsg, setSaveMsg] = useState<string | null>(null);
  const [expandedDay, setExpandedDay] = useState<DayKey | null>(null);

  useEffect(() => {
    const id = localStorage.getItem("yelen224_institution_id");
    if (!id) { setLoadError("Session expirée."); setLoading(false); return; }
    setInstitutionId(id);

    supabase.from("institutions").select("id,name,disponibilites").eq("id", id).maybeSingle().then(({ data, error }) => {
      if (error || !data) { setLoadError("Institution introuvable."); setLoading(false); return; }
      setInstitutionName(String(data.name ?? ""));
      setRules(parseToRules(data.disponibilites));
      setLoading(false);
    });
  }, []);

  const totalSlots = useMemo(() => generateSlots(rules).length, [rules]);
  const activeDays = useMemo(() => DAYS.filter(d => rules[d.key].active).length, [rules]);

  const onToggle = (key: DayKey, active: boolean) => {
    setRules(prev => ({ ...prev, [key]: { ...prev[key], active } }));
    if (active && expandedDay !== key) setExpandedDay(key);
    if (!active && expandedDay === key) setExpandedDay(null);
  };

  const onRule = (key: DayKey, patch: Partial<DayRule>) =>
    setRules(prev => ({ ...prev, [key]: { ...prev[key], ...patch } }));

  const handleSave = useCallback(async () => {
    if (!institutionId) return;
    setSaveMsg(null); setLoadError(null);
    for (const d of DAYS) {
      const r = rules[d.key];
      if (!r.active) continue;
      if (!r.start || !r.end) { setLoadError(`${d.label} : heure début et fin requises.`); return; }
      const s = toMin(r.start), e = toMin(r.end);
      if (s === null || e === null) { setLoadError(`${d.label} : format invalide.`); return; }
      if (e <= s) { setLoadError(`${d.label} : fin doit être après début.`); return; }
    }
    setSaving(true);
    const { error } = await supabase.from("institutions").update({ disponibilites: generateSlots(rules) }).eq("id", institutionId);
    setSaving(false);
    if (error) { setLoadError(error.message); return; }
    router.push(`/institution/${institutionId}/dashboard`);
  }, [institutionId, rules]);

  // ── Couleurs thème ──
  const bg      = isDark ? "#0D1117" : "#f8f8fb";
  const cardBg  = isDark ? "#161B22" : "#ffffff";
  const cardBrd = isDark ? "rgba(255,255,255,0.07)" : "rgba(0,0,0,0.07)";
  const txt1    = isDark ? "#F0F6FC" : "#0d0d1a";
  const txt2    = isDark ? "#8B949E" : "#555";
  const txt3    = isDark ? "#6E7681" : "#888";
  const hdrBg   = isDark ? "rgba(10,12,18,0.98)" : "rgba(255,255,255,0.98)";
  const inputBg = isDark ? "rgba(255,255,255,0.04)" : "#f5f5f8";

  if (loading) return (
    <div style={{ minHeight: "100vh", backgroundColor: bg, display: "flex", alignItems: "center", justifyContent: "center" }}>
      <YelenLoader size={36}/>
    </div>
  );

  return (
    <div style={{ minHeight: "100vh", backgroundColor: bg, color: txt1, fontFamily: "'Inter',-apple-system,sans-serif", transition: "background-color 0.3s" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap');
        *{box-sizing:border-box}
        @keyframes spin{to{transform:rotate(360deg)}}
        @keyframes fadeUp{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}
        @keyframes slideDown{from{opacity:0;max-height:0}to{opacity:1;max-height:400px}}
        input[type=time]{color-scheme:${isDark ? "dark" : "light"}}
        select option{background:${isDark ? "#161B22" : "#fff"};color:${txt1}}
        .day-row:hover{border-color:rgba(245,166,35,0.3)!important}
        .day-row{transition:all 0.15s}
        .toggle-track{transition:background-color 0.2s}
        .toggle-thumb{transition:left 0.2s}
        .dur-btn:hover{border-color:rgba(245,166,35,0.5)!important}
        .dur-btn{transition:all 0.15s;cursor:pointer}
      `}</style>

      {/* ── HEADER ── */}
      <header style={{ position: "sticky", top: 0, zIndex: 100, backgroundColor: hdrBg, borderBottom: `1px solid ${cardBrd}`, backdropFilter: "blur(20px)", padding: "0 24px" }}>
        <div style={{ maxWidth: "800px", margin: "0 auto", height: "60px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          <Link href="/" style={{ display: "flex", alignItems: "center", gap: "10px", textDecoration: "none" }}>
            <div style={{ width: "34px", height: "34px", backgroundColor: "#F5A623", borderRadius: "8px", display: "flex", alignItems: "center", justifyContent: "center" }}>
              <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="#080812" strokeWidth="2.5" strokeLinecap="round">
                <circle cx="12" cy="12" r="3"/>
                <path d="M12 2v3M12 19v3M4.22 4.22l2.12 2.12M17.66 17.66l2.12 2.12M2 12h3M19 12h3M4.22 19.78l2.12-2.12M17.66 6.34l2.12-2.12"/>
              </svg>
            </div>
            <div>
              <p style={{ color: isDark ? "#fff" : "#0d0d1a", fontSize: "14px", fontWeight: "800", margin: 0, lineHeight: 1 }}>YELEN224</p>
              <p style={{ color: "#F5A623", fontSize: "8px", margin: 0, letterSpacing: "1.5px", fontWeight: "600" }}>REPUBLIQUE DE GUINEE</p>
            </div>
          </Link>
          <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
            <ThemeToggle />
            <Link href="/institution/dashboard" style={{ fontSize: "13px", color: txt2, textDecoration: "none", padding: "7px 14px", borderRadius: "8px", border: `1px solid ${cardBrd}` }}>
              ← Dashboard
            </Link>
          </div>
        </div>
      </header>

      <main style={{ maxWidth: "800px", margin: "0 auto", padding: "32px 24px 80px" }}>

        {/* Titre */}
        <div style={{ marginBottom: "28px", animation: "fadeUp 0.3s ease" }}>
          <p style={{ color: "#F5A623", fontSize: "11px", letterSpacing: "2px", textTransform: "uppercase", margin: "0 0 6px", fontWeight: "700" }}>
            Gestion des créneaux
          </p>
          <h1 style={{ color: txt1, fontSize: "26px", fontWeight: "900", margin: "0 0 6px", letterSpacing: "-0.5px" }}>
            Disponibilités
          </h1>
          <p style={{ color: txt2, fontSize: "13px", margin: 0 }}>
            Configurez vos jours et heures d&apos;ouverture. Les citoyens pourront réserver uniquement sur ces créneaux.
          </p>
        </div>

        {/* ── STATS RÉSUMÉ ── */}
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: "12px", marginBottom: "24px" }}>
          {[
            { label: "Jours actifs", value: `${activeDays} / 7`, icon: "📅", color: "#F5A623" },
            { label: "Créneaux totaux", value: String(totalSlots), icon: "🕐", color: "#22c55e" },
            { label: "Institution", value: institutionName || "—", icon: "🏛️", color: "#3b82f6" },
          ].map(s => (
            <div key={s.label} style={{ backgroundColor: cardBg, border: `1px solid ${cardBrd}`, borderRadius: "14px", padding: "16px" }}>
              <div style={{ fontSize: "20px", marginBottom: "8px" }}>{s.icon}</div>
              <div style={{ fontSize: "20px", fontWeight: "900", color: s.color, lineHeight: 1, marginBottom: "4px" }}>{s.value}</div>
              <div style={{ fontSize: "11px", color: txt3, textTransform: "uppercase", letterSpacing: "0.5px" }}>{s.label}</div>
            </div>
          ))}
        </div>

        {/* Erreur / Succès */}
        {loadError && (
          <div style={{ backgroundColor: "rgba(239,68,68,0.08)", border: "1px solid rgba(239,68,68,0.25)", borderRadius: "10px", padding: "12px 16px", marginBottom: "16px" }}>
            <p style={{ color: "#ef4444", fontSize: "13px", margin: 0 }}>⚠️ {loadError}</p>
          </div>
        )}
        {saveMsg && (
          <div style={{ backgroundColor: "rgba(34,197,94,0.08)", border: "1px solid rgba(34,197,94,0.25)", borderRadius: "10px", padding: "12px 16px", marginBottom: "16px" }}>
            <p style={{ color: "#22c55e", fontSize: "13px", margin: 0 }}>✅ {saveMsg}</p>
          </div>
        )}

        {/* ── JOURS ── */}
        <div style={{ display: "flex", flexDirection: "column", gap: "10px", marginBottom: "28px" }}>
          {DAYS.map((d, idx) => {
            const r = rules[d.key];
            const slots = countSlots(rules, d.key);
            const isExpanded = expandedDay === d.key || r.active;

            return (
              <div key={d.key} className="day-row" style={{ backgroundColor: cardBg, border: `1px solid ${r.active ? "rgba(245,166,35,0.25)" : cardBrd}`, borderLeft: `3px solid ${r.active ? "#F5A623" : "transparent"}`, borderRadius: "14px", overflow: "hidden", animation: `fadeUp 0.2s ease ${idx * 0.03}s both` }}>

                {/* En-tête du jour */}
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "16px 20px", cursor: "pointer" }} onClick={() => setExpandedDay(expandedDay === d.key ? null : d.key)}>
                  <div style={{ display: "flex", alignItems: "center", gap: "14px" }}>
                    {/* Toggle */}
                    <div
                      className="toggle-track"
                      onClick={e => { e.stopPropagation(); onToggle(d.key, !r.active); }}
                      style={{ width: "42px", height: "24px", borderRadius: "12px", backgroundColor: r.active ? "#F5A623" : (isDark ? "rgba(255,255,255,0.1)" : "rgba(0,0,0,0.1)"), position: "relative", cursor: "pointer", flexShrink: 0 }}
                    >
                      <div className="toggle-thumb" style={{ position: "absolute", top: "3px", left: r.active ? "21px" : "3px", width: "18px", height: "18px", borderRadius: "50%", backgroundColor: r.active ? "#080812" : (isDark ? "#6E7681" : "#aaa") }} />
                    </div>

                    <div>
                      <span style={{ color: r.active ? txt1 : txt2, fontSize: "14px", fontWeight: "700" }}>{d.label}</span>
                      {r.active && r.start && r.end && (
                        <span style={{ marginLeft: "10px", color: txt3, fontSize: "12px" }}>{r.start} – {r.end}</span>
                      )}
                    </div>
                  </div>

                  <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                    {r.active && slots > 0 && (
                      <span style={{ backgroundColor: "rgba(245,166,35,0.1)", border: "1px solid rgba(245,166,35,0.25)", color: "#F5A623", fontSize: "11px", fontWeight: "700", padding: "2px 8px", borderRadius: "20px" }}>
                        {slots} créneaux
                      </span>
                    )}
                    {!r.active && (
                      <span style={{ color: txt3, fontSize: "11px", fontStyle: "italic" }}>Fermé</span>
                    )}
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke={txt3} strokeWidth={2} style={{ transform: (isExpanded && expandedDay === d.key) ? "rotate(180deg)" : "rotate(0)", transition: "transform 0.2s" }}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7"/>
                    </svg>
                  </div>
                </div>

                {/* Contenu expandé */}
                {r.active && (
                  <div style={{ padding: "0 20px 20px", borderTop: `1px solid ${cardBrd}` }}>
                    <div style={{ paddingTop: "16px", display: "grid", gridTemplateColumns: "1fr 1fr", gap: "14px" }}>
                      {/* Début */}
                      <div>
                        <label style={{ color: txt3, fontSize: "11px", fontWeight: "600", textTransform: "uppercase", letterSpacing: "0.8px", display: "block", marginBottom: "8px" }}>
                          Heure d&apos;ouverture
                        </label>
                        <input
                          type="time"
                          value={r.start}
                          onChange={e => onRule(d.key, { start: e.target.value })}
                          style={{ width: "100%", backgroundColor: inputBg, border: `1px solid ${cardBrd}`, borderRadius: "10px", padding: "11px 14px", color: txt1, fontSize: "14px", fontFamily: "inherit", outline: "none" }}
                        />
                      </div>

                      {/* Fin */}
                      <div>
                        <label style={{ color: txt3, fontSize: "11px", fontWeight: "600", textTransform: "uppercase", letterSpacing: "0.8px", display: "block", marginBottom: "8px" }}>
                          Heure de fermeture
                        </label>
                        <input
                          type="time"
                          value={r.end}
                          onChange={e => onRule(d.key, { end: e.target.value })}
                          style={{ width: "100%", backgroundColor: inputBg, border: `1px solid ${cardBrd}`, borderRadius: "10px", padding: "11px 14px", color: txt1, fontSize: "14px", fontFamily: "inherit", outline: "none" }}
                        />
                      </div>
                    </div>

                    {/* Durée RDV */}
                    <div style={{ marginTop: "14px" }}>
                      <label style={{ color: txt3, fontSize: "11px", fontWeight: "600", textTransform: "uppercase", letterSpacing: "0.8px", display: "block", marginBottom: "10px" }}>
                        Durée par rendez-vous
                      </label>
                      <div style={{ display: "flex", gap: "8px" }}>
                        {DURATIONS.map(dur => (
                          <button
                            key={dur}
                            className="dur-btn"
                            onClick={() => onRule(d.key, { duration: dur })}
                            style={{ flex: 1, backgroundColor: r.duration === dur ? "rgba(245,166,35,0.12)" : inputBg, border: `1px solid ${r.duration === dur ? "rgba(245,166,35,0.4)" : cardBrd}`, borderRadius: "10px", padding: "10px 8px", color: r.duration === dur ? "#F5A623" : txt2, fontSize: "13px", fontWeight: r.duration === dur ? "800" : "500" }}
                          >
                            {dur} min
                          </button>
                        ))}
                      </div>
                    </div>

                    {/* Aperçu créneaux */}
                    {r.start && r.end && slots > 0 && (
                      <div style={{ marginTop: "14px", backgroundColor: isDark ? "rgba(245,166,35,0.04)" : "rgba(245,166,35,0.05)", border: "1px solid rgba(245,166,35,0.15)", borderRadius: "10px", padding: "12px 14px" }}>
                        <p style={{ color: "#F5A623", fontSize: "11px", fontWeight: "700", margin: "0 0 6px", textTransform: "uppercase", letterSpacing: "0.5px" }}>
                          Aperçu — {slots} créneaux générés
                        </p>
                        <div style={{ display: "flex", flexWrap: "wrap", gap: "6px" }}>
                          {(() => {
                            const s = toMin(r.start), e = toMin(r.end);
                            if (s === null || e === null) return null;
                            const preview: string[] = [];
                            for (let t = s; t + r.duration <= e && preview.length < 8; t += r.duration) preview.push(toHHMM(t));
                            return preview.map(h => (
                              <span key={h} style={{ backgroundColor: isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.05)", border: `1px solid ${cardBrd}`, borderRadius: "8px", padding: "3px 8px", fontSize: "11px", color: txt2, fontWeight: "500" }}>{h}</span>
                            ));
                          })()}
                          {slots > 8 && <span style={{ color: txt3, fontSize: "11px", alignSelf: "center" }}>+{slots - 8} autres</span>}
                        </div>
                      </div>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>

        {/* ── BOUTON SAUVEGARDER ── */}
        <div style={{ position: "sticky", bottom: "24px" }}>
          <button
            onClick={handleSave}
            disabled={saving}
            style={{ width: "100%", backgroundColor: saving ? (isDark ? "rgba(255,255,255,0.1)" : "rgba(0,0,0,0.1)") : "#F5A623", color: saving ? txt3 : "#080812", border: "none", borderRadius: "14px", padding: "17px", fontSize: "15px", fontWeight: "800", cursor: saving ? "not-allowed" : "pointer", boxShadow: saving ? "none" : "0 4px 24px rgba(245,166,35,0.4)", transition: "all 0.2s", letterSpacing: "0.3px", display: "flex", alignItems: "center", justifyContent: "center", gap: "8px" }}
          >
            {saving ? <><YelenLoader size={16} color={txt3}/>Sauvegarde en cours…</> : `Sauvegarder — ${totalSlots} créneaux`}
          </button>
        </div>
      </main>
    </div>
  );
}

"use client";

// ═══════════════════════════════════════════════════════════════════════
// YELEN224 — /app/institution/dashboard/page.tsx
// RÔLE : Point d'entrée unique du dashboard institution.
//        - Si connecté  → lit l'institution_id depuis la session Supabase
//                       → redirige vers /institution/[id]/dashboard
//        - Si non conn. → affiche l'écran de connexion pro
// ═══════════════════════════════════════════════════════════════════════

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { supabase } from "@/lib/supabase";
import { YelenLoader } from "@/components/YelenLoader";

// ─── Design Tokens (identiques au dashboard principal) ────────────────
const T = {
  gold:   "#D4A017",
  goldD:  "#A07810",
  bg:     "#0A0A0F",
  bgCard: "#111118",
  bg3:    "#1C1C28",
  border: "rgba(255,255,255,0.07)",
  brd2:   "rgba(255,255,255,0.12)",
  t1:     "#FFFFFF",
  t2:     "#9999B3",
  t3:     "#55556A",
  green:  "#00C896",
  greenL: "rgba(0,200,150,0.12)",
  red:    "#FF4757",
  redL:   "rgba(255,71,87,0.12)",
  blue:   "#4F8EF7",
};

// ─── SVG Icons ────────────────────────────────────────────────────────
const Ic = {
  Lock: () => (
    <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke={T.gold} strokeWidth="1.8" strokeLinecap="round">
      <rect x="3" y="11" width="18" height="11" rx="2"/>
      <path d="M7 11V7a5 5 0 0 1 10 0v4"/>
    </svg>
  ),
  Building: () => (
    <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke={T.gold} strokeWidth="1.5" strokeLinecap="round">
      <path d="M3 21h18"/>
      <path d="M5 21V7l8-4v18"/>
      <path d="M19 21V11l-6-4"/>
      <path d="M9 9h1"/><path d="M9 13h1"/><path d="M9 17h1"/>
    </svg>
  ),
  Eye: (show: boolean) => (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke={T.t3} strokeWidth="2" strokeLinecap="round">
      {show ? (
        <><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94"/><path d="M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19"/><line x1="1" y1="1" x2="23" y2="23"/></>
      ) : (
        <><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></>
      )}
    </svg>
  ),
  Arrow: () => (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
      <line x1="5" y1="12" x2="19" y2="12"/>
      <polyline points="12 5 19 12 12 19"/>
    </svg>
  ),
  Warning: () => (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke={T.red} strokeWidth="2" strokeLinecap="round">
      <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/>
      <line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/>
    </svg>
  ),
  Check: () => (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke={T.green} strokeWidth="2.5" strokeLinecap="round">
      <polyline points="20 6 9 17 4 12"/>
    </svg>
  ),
  Mail: () => (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke={T.t3} strokeWidth="1.8" strokeLinecap="round">
      <path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/>
      <polyline points="22,6 12,13 2,6"/>
    </svg>
  ),
  KeyIcon: () => (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke={T.t3} strokeWidth="1.8" strokeLinecap="round">
      <path d="M21 2l-2 2m-7.61 7.61a5.5 5.5 0 1 1-7.778 7.778 5.5 5.5 0 0 1 7.777-7.777zm0 0L15.5 7.5m0 0l3 3L22 7l-3-3m-3.5 3.5L19 4"/>
    </svg>
  ),
};

// ─── States ───────────────────────────────────────────────────────────
type PageState = "checking" | "not_connected" | "connecting" | "redirecting" | "error_no_institution";

export default function InstitutionDashboardGateway() {
  const router = useRouter();
  const [pageState, setPageState] = useState<PageState>("checking");
  const [email, setEmail]       = useState("");
  const [password, setPassword] = useState("");
  const [showPwd, setShowPwd]   = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [loading, setLoading]   = useState(false);

  // ── Au montage : vérifier la session existante ──
  useEffect(() => {
    (async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session?.user) {
        setPageState("not_connected");
        return;
      }
      await resolveAndRedirect(session.user.id);
    })();
  }, []);

  // ── Résolution institution_id depuis user_id ──
  async function resolveAndRedirect(userId: string) {
    setPageState("redirecting");

    // 1. Chercher dans la table "institutions" si l'utilisateur en est le gestionnaire
    const { data: instByOwner } = await supabase
      .from("institutions")
      .select("id")
      .eq("user_id", userId)
      .maybeSingle();

    if (instByOwner?.id) {
      router.replace(`/institution/${instByOwner.id}/dashboard`);
      return;
    }

    // 2. Chercher dans une table de liaison "institution_members" ou "gestionnaires"
    const { data: memberRow } = await supabase
      .from("institution_members")
      .select("institution_id")
      .eq("user_id", userId)
      .maybeSingle();

    if (memberRow?.institution_id) {
      router.replace(`/institution/${memberRow.institution_id}/dashboard`);
      return;
    }

    // 3. Chercher dans la table "users" le champ institution_id
    const { data: userRow } = await supabase
      .from("users")
      .select("institution_id")
      .eq("id", userId)
      .maybeSingle();

    if (userRow?.institution_id) {
      router.replace(`/institution/${userRow.institution_id}/dashboard`);
      return;
    }

    // Aucune institution trouvée pour cet utilisateur
    setPageState("error_no_institution");
  }

  // ── Connexion ──
  async function handleLogin(e: React.FormEvent) {
    e.preventDefault();
    if (!email || !password) return;
    setLoading(true);
    setLoginError(null);
    setPageState("connecting");

    const { data, error } = await supabase.auth.signInWithPassword({ email, password });

    if (error) {
      setLoginError(
        error.message.includes("Invalid") || error.message.includes("credentials")
          ? "Email ou mot de passe incorrect."
          : error.message.includes("confirmed")
          ? "Votre email n'est pas encore confirmé."
          : "Erreur de connexion. Réessayez."
      );
      setPageState("not_connected");
      setLoading(false);
      return;
    }

    if (data.user) {
      await resolveAndRedirect(data.user.id);
    }
    setLoading(false);
  }

  // ── CSS ──
  const css = `
    *{box-sizing:border-box;-webkit-tap-highlight-color:transparent;margin:0;padding:0}
    html,body{background:${T.bg};overflow-x:hidden}
    ::-webkit-scrollbar{display:none}
    @keyframes fadeUp{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}
    @keyframes shimmer{0%{background-position:-200% 0}100%{background-position:200% 0}}
    .tap{transition:opacity .12s,transform .12s;cursor:pointer;user-select:none;touch-action:manipulation}
    .tap:active{opacity:.65;transform:scale(.97)}
    input::placeholder{color:${T.t3}}
    input{color:${T.t1};background:transparent;border:none;outline:none;font-family:inherit;width:100%}
    .field:focus-within{border-color:${T.gold}50 !important}
  `;

  // ─────────── CHECKING ───────────────────────────────────────────────
  if (pageState === "checking" || pageState === "redirecting") {
    return (
      <div style={{ minHeight: "100svh", backgroundColor: T.bg, display: "flex", alignItems: "center", justifyContent: "center", flexDirection: "column", gap: "20px" }}>
        <style>{css}</style>
        <YelenLoader size={56}/>
        <div style={{ textAlign: "center" }}>
          <div style={{ color: T.t2, fontSize: "13px", fontWeight: "700", letterSpacing: "0.3px" }}>
            {pageState === "redirecting" ? "Connexion en cours…" : "Vérification de la session…"}
          </div>
          <div style={{ color: T.t3, fontSize: "11px", marginTop: "4px" }}>YELEN224 Dashboard</div>
        </div>
      </div>
    );
  }

  // ─────────── ERROR: COMPTE SANS INSTITUTION ─────────────────────────
  if (pageState === "error_no_institution") {
    return (
      <div style={{ minHeight: "100svh", backgroundColor: T.bg, display: "flex", alignItems: "center", justifyContent: "center", padding: "24px" }}>
        <style>{css}</style>
        <div style={{ backgroundColor: T.bgCard, borderRadius: "24px", padding: "32px 24px", border: `1px solid ${T.border}`, textAlign: "center", maxWidth: "360px", width: "100%", animation: "fadeUp 0.3s ease" }}>
          <div style={{ width: "56px", height: "56px", borderRadius: "16px", backgroundColor: T.redL, display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 16px" }}>
            {Ic.Warning()}
          </div>
          <div style={{ color: T.t1, fontSize: "17px", fontWeight: "900", marginBottom: "8px", letterSpacing: "-0.3px" }}>Aucune institution liée</div>
          <div style={{ color: T.t2, fontSize: "13px", lineHeight: 1.7, marginBottom: "24px" }}>
            Votre compte est connecté mais n&apos;est associé à aucune institution sur YELEN224.<br/>
            Contactez l&apos;administrateur ou créez votre espace institution.
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            <Link href="/institution/inscription" style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: "8px", background: `linear-gradient(135deg, ${T.gold}, ${T.goldD})`, color: "#000", fontWeight: "800", fontSize: "14px", padding: "13px", borderRadius: "12px", textDecoration: "none" }} className="tap">
              Créer mon institution
            </Link>
            <button onClick={async () => { await supabase.auth.signOut(); setEmail(""); setPassword(""); setPageState("not_connected"); }} style={{ background: T.bg3, border: `1px solid ${T.border}`, borderRadius: "12px", padding: "12px", color: T.t2, fontWeight: "700", fontSize: "13px", cursor: "pointer" }} className="tap">
              Se déconnecter
            </button>
          </div>
        </div>
      </div>
    );
  }

  // ─────────── NOT CONNECTED — ÉCRAN DE CONNEXION PRO ─────────────────
  return (
    <div style={{ minHeight: "100svh", backgroundColor: T.bg, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: "24px", fontFamily: "-apple-system,'SF Pro Display','Helvetica Neue',sans-serif" }}>
      <style>{css}</style>

      {/* Fond décoratif */}
      <div style={{ position: "fixed", top: "10%", left: "50%", transform: "translateX(-50%)", width: "300px", height: "300px", borderRadius: "50%", background: `radial-gradient(circle, ${T.gold}08 0%, transparent 70%)`, pointerEvents: "none" }}/>

      <div style={{ width: "100%", maxWidth: "380px", animation: "fadeUp 0.3s ease" }}>

        {/* Logo + Branding */}
        <div style={{ textAlign: "center", marginBottom: "32px" }}>
          <div style={{ width: "64px", height: "64px", borderRadius: "20px", background: `linear-gradient(135deg, ${T.gold}25, ${T.goldD}15)`, border: `1px solid ${T.gold}30`, display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 14px" }}>
            {Ic.Building()}
          </div>
          <div style={{ color: T.t1, fontSize: "22px", fontWeight: "900", letterSpacing: "-0.5px" }}>YELEN224</div>
          <div style={{ color: T.t3, fontSize: "12px", fontWeight: "600", letterSpacing: "1.5px", textTransform: "uppercase", marginTop: "4px" }}>Espace Institution</div>
        </div>

        {/* Card formulaire */}
        <div style={{ backgroundColor: T.bgCard, borderRadius: "24px", padding: "24px", border: `1px solid ${T.border}` }}>
          <div style={{ color: T.t1, fontSize: "17px", fontWeight: "900", letterSpacing: "-0.3px", marginBottom: "4px" }}>Connexion</div>
          <div style={{ color: T.t3, fontSize: "12px", marginBottom: "22px" }}>Accédez à votre tableau de bord institution</div>

          {/* Erreur */}
          {loginError && (
            <div style={{ backgroundColor: T.redL, border: `1px solid ${T.red}30`, borderRadius: "12px", padding: "11px 13px", marginBottom: "16px", display: "flex", alignItems: "center", gap: "8px" }}>
              {Ic.Warning()}
              <span style={{ color: T.red, fontSize: "12px", fontWeight: "700" }}>{loginError}</span>
            </div>
          )}

          <form onSubmit={handleLogin} style={{ display: "flex", flexDirection: "column", gap: "12px" }}>

            {/* Email */}
            <div>
              <label style={{ color: T.t3, fontSize: "10px", fontWeight: "700", textTransform: "uppercase", letterSpacing: "0.6px", display: "block", marginBottom: "6px" }}>Adresse email</label>
              <div className="field" style={{ backgroundColor: T.bg3, border: `1px solid ${T.border}`, borderRadius: "12px", padding: "0 13px", display: "flex", alignItems: "center", gap: "10px", transition: "border-color 0.2s" }}>
                {Ic.Mail()}
                <input
                  type="email"
                  value={email}
                  onChange={e => setEmail(e.target.value)}
                  placeholder="contact@institution.fr"
                  autoComplete="email"
                  style={{ padding: "12px 0", fontSize: "14px" }}
                  required
                />
              </div>
            </div>

            {/* Mot de passe */}
            <div>
              <label style={{ color: T.t3, fontSize: "10px", fontWeight: "700", textTransform: "uppercase", letterSpacing: "0.6px", display: "block", marginBottom: "6px" }}>Mot de passe</label>
              <div className="field" style={{ backgroundColor: T.bg3, border: `1px solid ${T.border}`, borderRadius: "12px", padding: "0 13px", display: "flex", alignItems: "center", gap: "10px", transition: "border-color 0.2s" }}>
                {Ic.KeyIcon()}
                <input
                  type={showPwd ? "text" : "password"}
                  value={password}
                  onChange={e => setPassword(e.target.value)}
                  placeholder="••••••••••"
                  autoComplete="current-password"
                  style={{ padding: "12px 0", fontSize: "14px" }}
                  required
                />
                <button type="button" onClick={() => setShowPwd(p => !p)} style={{ background: "none", border: "none", cursor: "pointer", padding: "4px", flexShrink: 0 }}>
                  {Ic.Eye(showPwd)}
                </button>
              </div>
            </div>

            {/* Mot de passe oublié */}
            <div style={{ textAlign: "right", marginTop: "-4px" }}>
              <Link href="/institution/reset-password" style={{ color: T.gold, fontSize: "11px", fontWeight: "700", textDecoration: "none" }}>
                Mot de passe oublié ?
              </Link>
            </div>

            {/* Bouton connexion */}
            <button
              type="submit"
              disabled={loading || !email || !password}
              style={{ background: loading || !email || !password ? T.bg3 : `linear-gradient(135deg, ${T.gold}, ${T.goldD})`, color: loading || !email || !password ? T.t3 : "#000", fontWeight: "800", fontSize: "15px", padding: "14px", borderRadius: "14px", border: "none", cursor: loading || !email || !password ? "not-allowed" : "pointer", display: "flex", alignItems: "center", justifyContent: "center", gap: "8px", transition: "all 0.2s", marginTop: "4px" }}
              className="tap"
            >
              {loading ? (
                <>
                  <YelenLoader size={16} color="#000"/>
                  Connexion en cours…
                </>
              ) : (
                <>
                  {Ic.Lock()}
                  Se connecter
                  {Ic.Arrow()}
                </>
              )}
            </button>
          </form>

          {/* Séparateur */}
          <div style={{ display: "flex", alignItems: "center", gap: "12px", margin: "20px 0" }}>
            <div style={{ flex: 1, height: "1px", backgroundColor: T.border }}/>
            <span style={{ color: T.t3, fontSize: "11px" }}>ou</span>
            <div style={{ flex: 1, height: "1px", backgroundColor: T.border }}/>
          </div>

          {/* Lien inscription */}
          <Link href="/institution/inscription" style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: "8px", backgroundColor: T.bg3, border: `1px solid ${T.border}`, borderRadius: "14px", padding: "13px", color: T.t1, fontWeight: "700", fontSize: "13px", textDecoration: "none" }} className="tap">
            Créer un espace institution
          </Link>
        </div>

        {/* Features pro */}
        <div style={{ marginTop: "20px", display: "flex", flexDirection: "column", gap: "8px" }}>
          {[
            "Tableau de bord analytique temps réel",
            "Gestion des rendez-vous et citoyens",
            "Avis et réputation en ligne",
          ].map((f, i) => (
            <div key={i} style={{ display: "flex", alignItems: "center", gap: "10px" }}>
              <div style={{ width: "18px", height: "18px", borderRadius: "50%", backgroundColor: T.greenL, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                {Ic.Check()}
              </div>
              <span style={{ color: T.t2, fontSize: "12px" }}>{f}</span>
            </div>
          ))}
        </div>

        {/* Footer */}
        <div style={{ textAlign: "center", marginTop: "24px", color: T.t3, fontSize: "10px" }}>
          YELEN224 · Plateforme de gestion institutionnelle
        </div>
      </div>
    </div>
  );
}

