import { YelenLoader } from "@/components/YelenLoader";
import { DEVISE_LABEL } from "@/lib/devise";

// ─── Types ────────────────────────────────────────────────────────────
type PaidService = {
  id: string;
  institution_id: string;
  nom: string;
  prix: number;
  duree_minutes: number;
  description: string | null;
  is_active: boolean;
