"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { supabase } from "@/lib/supabase";
import { YelenLoader } from "@/components/YelenLoader";

type Stats = {
  total_rdv: number;
  rdv_termine: number;
  rdv_annule: number;
  rdv_en_attente: number;
  taux_presence: number;
  total_avis: number;
  moyenne_avis: number;
  avis_5: number;
  avis_4: number;
  avis_3: number;
  avis_2: number;
  avis_1: number;
  rdv_par_mois: { mois: string; count: number }[];
};

type Institution = {
  name: string;
  category: string;
  ville: string;
  logo: string | null;
  badge_verifie: boolean;
};

export default function StatistiquesInstitution() {
  const router = useRouter();
  const [stats, setStats] = useState<Stats | null>(null);
  const [institution, setInstitution] = useState<Institution | null>(null);
  const [loading, setLoading] = useState(true);
  const [periode, setPeriode] = useState<"7j" | "30j" | "90j" | "tout">("30j");

  const fetchStats = async () => {
    setLoading(true);
    const id = localStorage.getItem("institutionId");
    if (!id) { router.push("/institution/inscription"); return; }

    const instRes = await supabase
      .from("institutions")
      .select("name, category, ville, logo, badge_verifie")
      .eq("id", id)
      .single();

    setInstitution(instRes.data || null);

    let dateFilter = new Date();
    if (periode === "7j") dateFilter.setDate(dateFilter.getDate() - 7);
    else if (periode === "30j") dateFilter.setDate(dateFilter.getDate() - 30);
    else if (periode === "90j") dateFilter.setDate(dateFilter.getDate() - 90);
    else dateFilter = new Date("2020-01-01");

    const dateStr = dateFilter.toISOString();

    const [rdvRes, avisRes] = await Promise.all([
      supabase.from("rdv").select("id, statut, presence, created_at").eq("institution_id", id).gte("created_at", dateStr),
      supabase.from("avis").select("id, note, created_at").eq("institution_id", id).gte("created_at", dateStr),
    ]);

    const rdvs = rdvRes.data || [];
    const avis = avisRes.data || [];

    const total_rdv = rdvs.length;
    const rdv_termine = rdvs.filter((r) => r.statut === "termine").length;
    const rdv_annule = rdvs.filter((r) => r.statut === "annule").length;
    const rdv_en_attente = rdvs.filter((r) => r.statut === "en_attente" || r.statut === "confirme").length;
    const presents = rdvs.filter((r) => r.presence === true).length;
    const taux_presence = rdv_termine > 0 ? Math.round((presents / rdv_termine) * 100) : 0;

    const total_avis = avis.length;
    const moyenne_avis = total_avis > 0 ? Math.round((avis.reduce((acc, a) => acc + a.note, 0) / total_avis) * 10) / 10 : 0;

    const rdv_par_mois: { mois: string; count: number }[] = [];
    const moisMap: Record<string, number> = {};
    rdvs.forEach((r) => {
      const m = new Date(r.created_at).toLocaleDateString("fr-FR", { month: "short", year: "2-digit" });
      moisMap[m] = (moisMap[m] || 0) + 1;
    });
    Object.entries(moisMap).forEach(([mois, count]) => rdv_par_mois.push({ mois, count }));

    setStats({
      total_rdv,
      rdv_termine,
      rdv_annule,
      rdv_en_attente,
      taux_presence,
      total_avis,
      moyenne_avis,
      avis_5: avis.filter((a) => a.note === 5).length,
      avis_4: avis.filter((a) => a.note === 4).length,
      avis_3: avis.filter((a) => a.note === 3).length,
      avis_2: avis.filter((a) => a.note === 2).length,
      avis_1: avis.filter((a) => a.note === 1).length,
      rdv_par_mois,
    });

    setLoading(false);
  };

  useEffect(() => {
    fetchStats();
  }, [periode]);

  const maxRdvMois = stats ? Math.max(...stats.rdv_par_mois.map((r) => r.count), 1) : 1;

  const noteColor = (n: number) => {
    if (n >= 4.5) return "#22c55e";
    if (n >= 3.5) return "#84cc16";
    if (n >= 2.5) return "#eab308";
    if (n >= 1.5) return "#f97316";
    return "#ef4444";
  };

  const PERIODES = [
    { id: "7j", label: "7 jours" },
    { id: "30j", label: "30 jours" },
    { id: "90j", label: "90 jours" },
    { id: "tout", label: "Tout" },
  ] as const;

  if (loading) return (
    <div style={{ minHeight: "100vh", backgroundColor: "#080812", display: "flex", alignItems: "center", justifyContent: "center" }}>
      <YelenLoader size={40}/>
    </div>
  );

  return (
    <div style={{ minHeight: "100vh", backgroundColor: "#080812", fontFamily: "'Segoe UI', sans-serif", color: "#fff" }}>
      <style>{`
        @keyframes spin { to { transform: rotate(360deg); } }
        @keyframes fadeUp { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
        .card { animation: fadeUp 0.3s ease forwards; }
        .periode-btn:hover { border-color: rgba(245,166,35,0.4) !important; }
      `}</style>

      <header style={{ position: "sticky", top: 0, zIndex: 50, background: "rgba(8,8,18,0.97)", backdropFilter: "blur(20px)", borderBottom: "1px solid rgba(245,166,35,0.15)", padding: "0 24px" }}>
        <div style={{ maxWidth: "1100px", margin: "0 auto", height: "60px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
            <Link href="/institution/dashboard" style={{ color: "#555", fontSize: "20px", textDecoration: "none" }}>&#8592;</Link>
            <div style={{ width: "36px", height: "36px", borderRadius: "9px", backgroundColor: "rgba(245,166,35,0.1)", border: "1px solid rgba(245,166,35,0.2)", display: "flex", alignItems: "center", justifyContent: "center", overflow: "hidden" }}>
              {institution?.logo
                ? <img src={institution.logo} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                : <span style={{ color: "#F5A623", fontSize: "14px", fontWeight: "800" }}>{institution?.name?.[0]?.toUpperCase() || "Y"}</span>
              }
            </div>
            <div>
              <h1 style={{ color: "#fff", fontSize: "15px", fontWeight: "700", margin: 0 }}>{institution?.name || "Statistiques"}</h1>
              <p style={{ color: "#555", fontSize: "11px", margin: 0 }}>{institution?.category} — {institution?.ville}</p>
            </div>
          </div>
          <span style={{ color: "#F5A623", fontSize: "17px", fontWeight: "800", letterSpacing: "2px" }}>YELEN224</span>
        </div>
      </header>

      <main style={{ maxWidth: "1100px", margin: "0 auto", padding: "28px 24px 60px" }}>

        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: "24px", flexWrap: "wrap", gap: "12px" }}>
          <div>
            <p style={{ color: "#F5A623", fontSize: "11px", letterSpacing: "2px", textTransform: "uppercase", margin: "0 0 4px" }}>Tableau de bord analytique</p>
            <h2 style={{ color: "#fff", fontSize: "22px", fontWeight: "800", margin: 0 }}>Statistiques de performance</h2>
          </div>
          <div style={{ display: "flex", gap: "6px", backgroundColor: "rgba(255,255,255,0.03)", border: "1px solid rgba(255,255,255,0.07)", borderRadius: "10px", padding: "4px" }}>
            {PERIODES.map((p) => (
              <button
                key={p.id}
                className="periode-btn"
                onClick={() => setPeriode(p.id)}
                style={{ backgroundColor: periode === p.id ? "#F5A623" : "transparent", color: periode === p.id ? "#0D0D1A" : "#666", border: "none", borderRadius: "7px", padding: "6px 14px", fontSize: "12px", fontWeight: "700", cursor: "pointer", transition: "all 0.15s" }}
              >
                {p.label}
              </button>
            ))}
          </div>
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: "14px", marginBottom: "20px" }}>
          {[
            { label: "Total RDV", value: stats?.total_rdv || 0, sub: `${stats?.rdv_en_attente || 0} en attente`, color: "#F5A623" },
            { label: "RDV Termines", value: stats?.rdv_termine || 0, sub: `${stats?.rdv_annule || 0} annules`, color: "#22c55e" },
            { label: "Taux de presence", value: `${stats?.taux_presence || 0}%`, sub: "Citoyens presents", color: stats?.taux_presence && stats.taux_presence >= 70 ? "#22c55e" : "#f97316" },
            { label: "Note moyenne", value: stats?.moyenne_avis || "—", sub: `${stats?.total_avis || 0} avis`, color: noteColor(stats?.moyenne_avis || 0) },
          ].map((s, i) => (
            <div key={i} className="card" style={{ backgroundColor: "#0D0D1A", border: "1px solid rgba(255,255,255,0.06)", borderRadius: "14px", padding: "20px 22px", animationDelay: `${i * 0.05}s` }}>
              <p style={{ color: "#444", fontSize: "11px", textTransform: "uppercase", letterSpacing: "1px", margin: "0 0 10px" }}>{s.label}</p>
              <p style={{ color: s.color, fontSize: "32px", fontWeight: "800", margin: "0 0 4px", lineHeight: 1 }}>{s.value}</p>
              <p style={{ color: "#333", fontSize: "11px", margin: 0 }}>{s.sub}</p>
            </div>
          ))}
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "16px", marginBottom: "16px" }}>

          <div className="card" style={{ backgroundColor: "#0D0D1A", border: "1px solid rgba(255,255,255,0.06)", borderRadius: "14px", padding: "24px" }}>
            <h3 style={{ color: "#fff", fontSize: "14px", fontWeight: "700", margin: "0 0 20px" }}>Repartition des RDV</h3>
            {[
              { label: "Termines", value: stats?.rdv_termine || 0, total: stats?.total_rdv || 1, color: "#22c55e" },
              { label: "En attente", value: stats?.rdv_en_attente || 0, total: stats?.total_rdv || 1, color: "#F5A623" },
              { label: "Annules", value: stats?.rdv_annule || 0, total: stats?.total_rdv || 1, color: "#ef4444" },
            ].map((item, i) => (
              <div key={i} style={{ marginBottom: "14px" }}>
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "6px" }}>
                  <span style={{ color: "#888", fontSize: "12px" }}>{item.label}</span>
                  <span style={{ color: "#fff", fontSize: "12px", fontWeight: "700" }}>{item.value}</span>
                </div>
                <div style={{ height: "6px", backgroundColor: "rgba(255,255,255,0.05)", borderRadius: "3px", overflow: "hidden" }}>
                  <div style={{ width: `${(item.value / item.total) * 100}%`, height: "100%", backgroundColor: item.color, borderRadius: "3px", transition: "width 0.8s ease" }} />
                </div>
              </div>
            ))}

            <div style={{ marginTop: "24px", paddingTop: "20px", borderTop: "1px solid rgba(255,255,255,0.05)" }}>
              <h4 style={{ color: "#fff", fontSize: "13px", fontWeight: "700", margin: "0 0 14px" }}>Taux de presence</h4>
              <div style={{ display: "flex", alignItems: "center", gap: "16px" }}>
                <div style={{ position: "relative", width: "80px", height: "80px", flexShrink: 0 }}>
                  <svg viewBox="0 0 36 36" style={{ width: "80px", height: "80px", transform: "rotate(-90deg)" }}>
                    <circle cx="18" cy="18" r="15.9" fill="none" stroke="rgba(255,255,255,0.05)" strokeWidth="3" />
                    <circle cx="18" cy="18" r="15.9" fill="none"
                      stroke={stats?.taux_presence && stats.taux_presence >= 70 ? "#22c55e" : "#f97316"}
                      strokeWidth="3"
                      strokeDasharray={`${(stats?.taux_presence || 0)} 100`}
                      strokeLinecap="round"
                    />
                  </svg>
                  <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
                    <span style={{ color: "#fff", fontSize: "14px", fontWeight: "800" }}>{stats?.taux_presence || 0}%</span>
                  </div>
                </div>
                <div>
                  <p style={{ color: "#fff", fontSize: "13px", fontWeight: "600", margin: "0 0 4px" }}>
                    {stats?.taux_presence && stats.taux_presence >= 70 ? "Excellent" : stats?.taux_presence && stats.taux_presence >= 50 ? "Acceptable" : "A ameliorer"}
                  </p>
                  <p style={{ color: "#555", fontSize: "12px", margin: 0, lineHeight: "1.5" }}>
                    Des citoyens honourent leurs rendez-vous termines
                  </p>
                </div>
              </div>
            </div>
          </div>

          <div className="card" style={{ backgroundColor: "#0D0D1A", border: "1px solid rgba(255,255,255,0.06)", borderRadius: "14px", padding: "24px" }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: "20px" }}>
              <h3 style={{ color: "#fff", fontSize: "14px", fontWeight: "700", margin: 0 }}>Avis clients</h3>
              <div style={{ display: "flex", alignItems: "center", gap: "6px" }}>
                <span style={{ color: noteColor(stats?.moyenne_avis || 0), fontSize: "22px", fontWeight: "800" }}>{stats?.moyenne_avis || "—"}</span>
                <span style={{ color: noteColor(stats?.moyenne_avis || 0), fontSize: "18px" }}>&#9733;</span>
              </div>
            </div>

            {[5, 4, 3, 2, 1].map((n) => {
              const count = stats?.[`avis_${n}` as keyof Stats] as number || 0;
              const pct = stats?.total_avis ? Math.round((count / stats.total_avis) * 100) : 0;
              const colors: Record<number, string> = { 5: "#22c55e", 4: "#84cc16", 3: "#eab308", 2: "#f97316", 1: "#ef4444" };
              return (
                <div key={n} style={{ display: "flex", alignItems: "center", gap: "10px", marginBottom: "10px" }}>
                  <span style={{ color: colors[n], fontSize: "12px", width: "16px", textAlign: "right", flexShrink: 0 }}>{n}&#9733;</span>
                  <div style={{ flex: 1, height: "8px", backgroundColor: "rgba(255,255,255,0.05)", borderRadius: "4px", overflow: "hidden" }}>
                    <div style={{ width: `${pct}%`, height: "100%", backgroundColor: colors[n], borderRadius: "4px", transition: "width 0.8s ease" }} />
                  </div>
                  <span style={{ color: "#555", fontSize: "11px", width: "28px", flexShrink: 0 }}>{count}</span>
                </div>
              );
            })}

            <div style={{ marginTop: "20px", paddingTop: "16px", borderTop: "1px solid rgba(255,255,255,0.05)", display: "grid", gridTemplateColumns: "1fr 1fr", gap: "10px" }}>
              <div style={{ backgroundColor: "rgba(255,255,255,0.03)", borderRadius: "10px", padding: "12px", textAlign: "center" }}>
                <p style={{ color: "#444", fontSize: "10px", textTransform: "uppercase", letterSpacing: "0.8px", margin: "0 0 6px" }}>Total avis</p>
                <p style={{ color: "#fff", fontSize: "20px", fontWeight: "800", margin: 0 }}>{stats?.total_avis || 0}</p>
              </div>
              <div style={{ backgroundColor: "rgba(255,255,255,0.03)", borderRadius: "10px", padding: "12px", textAlign: "center" }}>
                <p style={{ color: "#444", fontSize: "10px", textTransform: "uppercase", letterSpacing: "0.8px", margin: "0 0 6px" }}>Satisfaction</p>
                <p style={{ color: noteColor(stats?.moyenne_avis || 0), fontSize: "20px", fontWeight: "800", margin: 0 }}>
                  {stats?.total_avis ? `${Math.round(((stats.avis_4 + stats.avis_5) / stats.total_avis) * 100)}%` : "—"}
                </p>
              </div>
            </div>
          </div>
        </div>

        {stats && stats.rdv_par_mois.length > 0 && (
          <div className="card" style={{ backgroundColor: "#0D0D1A", border: "1px solid rgba(255,255,255,0.06)", borderRadius: "14px", padding: "24px" }}>
            <h3 style={{ color: "#fff", fontSize: "14px", fontWeight: "700", margin: "0 0 24px" }}>Evolution des RDV</h3>
            <div style={{ display: "flex", alignItems: "flex-end", gap: "8px", height: "120px" }}>
              {stats.rdv_par_mois.map((item, i) => (
                <div key={i} style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: "6px", height: "100%" }}>
                  <span style={{ color: "#555", fontSize: "10px" }}>{item.count}</span>
                  <div style={{ width: "100%", backgroundColor: "rgba(245,166,35,0.15)", borderRadius: "4px 4px 0 0", overflow: "hidden", flex: 1, display: "flex", alignItems: "flex-end" }}>
                    <div style={{ width: "100%", backgroundColor: "#F5A623", borderRadius: "4px 4px 0 0", height: `${(item.count / maxRdvMois) * 100}%`, minHeight: "4px", transition: "height 0.8s ease" }} />
                  </div>
                  <span style={{ color: "#444", fontSize: "10px", textAlign: "center" }}>{item.mois}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        <div style={{ marginTop: "16px" }}>
          <Link href="/institution/dashboard" style={{ display: "inline-flex", alignItems: "center", gap: "8px", backgroundColor: "rgba(245,166,35,0.08)", border: "1px solid rgba(245,166,35,0.2)", borderRadius: "10px", padding: "10px 20px", color: "#F5A623", fontSize: "13px", fontWeight: "600", textDecoration: "none" }}>
            &#8592; Retour au dashboard
          </Link>
        </div>
      </main>
    </div>
  );
}

"use client";
// ═══════════════════════════════════════════════════════════════════════
// YELEN224 — Validation Paiement sur Place (côté Institution)
// Path : /app/institution/[id]/dashboard/valider-rdv/page.tsx
//
// ✅ Saisie du code Yelen 6 chiffres
// ✅ Recherche dans paid_bookings filtré par institution_id
// ✅ Affiche la fiche complète : citoyen, service, montant, date
// ✅ Actions : Valider paiement / Absent / Annuler
// ✅ UPDATE paid_bookings + rdv en atomique
// ✅ Historique des validations du jour
// ✅ JOIN users via citoyen_id (FK correcte)
// ✅ Colonnes manquantes gérées avec fallback gracieux
// ✅ Mobile first — inline styles — dark/light via ThemeProvider
// ═══════════════════════════════════════════════════════════════════════

import { supabase } from "@/lib/supabase";
import { useTheme } from "@/components/ThemeProvider";
import { T } from "@/lib/theme";
import Link from "next/link";
import { useParams } from "next/navigation";
import { useCallback, useEffect, useRef, useState } from "react";
import { YelenLoader } from "@/components/YelenLoader";
import { DEVISE_LABEL } from "@/lib/devise";

// ─── Types ────────────────────────────────────────────────────────────
type BookingStatut = "en_attente" | "confirme" | "termine" | "no_show" | "annule";

// Forme brute renvoyée par Supabase pour les deux requêtes paid_bookings
// (recherche par code + historique) — mêmes colonnes/relations.
type BookingRow = {
  id: string; confirmation_code: string; statut: BookingStatut; date_rdv: string; heure_rdv: string;
  paid_services: { nom: string | null; prix: number | null; duree_minutes: number | null } | null;
  users: { prenom: string | null; nom: string | null; phone: string | null } | null;
};

type BookingFound = {
  id: string;
  confirmation_code: string;
  statut: BookingStatut;
  date_rdv: string;
  heure_rdv: string;
  pour_autre: boolean;
  nom_autre: string | null;
  phone_autre: string | null;
  service_nom: string;
  service_prix: number;
  service_duree: number;
  citoyen_prenom: string | null;
  citoyen_nom: string | null;
  citoyen_phone: string | null;
  citoyen_email: string | null;
};

type HistoryEntry = {
  id: string;
  confirmation_code: string;
  statut: BookingStatut;
  date_rdv: string;
  heure_rdv: string;
  service_nom: string;
  service_prix: number;
  validated_at: string | null;
  citoyen_nom: string | null;
};

// ─── Helpers ──────────────────────────────────────────────────────────
function formatPrix(p: number): string {
  return p.toLocaleString("fr-FR") + " " + DEVISE_LABEL;
}

function formatDate(dateRdv: string, heureRdv: string): string {
  try {
    const d = new Date(`${dateRdv}T${heureRdv}:00`);
    if (isNaN(d.getTime())) return `${dateRdv} à ${heureRdv}`;
    return (
      d.toLocaleDateString("fr-FR", {
        weekday: "long",
        day: "numeric",
        month: "long",
      }) + ` à ${heureRdv}`
    );
  } catch {
    return `${dateRdv} à ${heureRdv}`;
  }
}

function formatTime(iso: string): string {
  try {
    return new Date(iso).toLocaleTimeString("fr-FR", {
      hour: "2-digit",
      minute: "2-digit",
    });
  } catch {
    return "";
  }
}

const STATUT_CONFIG: Record<
  BookingStatut,
  { label: string; color: string; bg: string; icon: string; desc: string }
> = {
  en_attente: {
    label: "En attente",
    color: "#F5A623",
    bg: "rgba(245,166,35,0.1)",
    icon: "⏳",
    desc: "En attente de validation",
  },
  confirme: {
    label: "Payé ✓",
    color: "#00C896",
    bg: "rgba(0,200,150,0.1)",
    icon: "✅",
    desc: "Paiement validé",
  },
  termine: {
    label: "Terminé",
    color: "#6C63FF",
    bg: "rgba(108,99,255,0.1)",
    icon: "🏁",
    desc: "RDV terminé",
  },
  annule: {
    label: "Annulé",
    color: "#FF4757",
    bg: "rgba(255,71,87,0.1)",
    icon: "❌",
    desc: "Réservation annulée",
  },
  no_show: {
    label: "Absent",
    color: "#A0A0B0",
    bg: "rgba(160,160,176,0.1)",
    icon: "👻",
    desc: "Citoyen absent",
  },
};

// ═══════════════════════════════════════════════════════════════════════
// COMPOSANT PRINCIPAL
// ═══════════════════════════════════════════════════════════════════════
export default function ValiderRdvPage() {
  const { theme } = useTheme();
  const C = T[theme];
  const isDark = theme === "dark";

  const params = useParams<{ id: string }>();
  const institutionId = (() => {
    const fromParams = Array.isArray(params?.id) ? params.id[0] : params?.id;
    if (fromParams && fromParams !== "undefined") return fromParams;
    if (typeof window !== "undefined") {
      return localStorage.getItem("yelen224_institution_id") ?? "";
    }
    return "";
  })();

  // ── State saisie code ─────────────────────────────────────────────
  const [digits, setDigits] = useState<string[]>(["", "", "", "", "", ""]);
  const inputRefs = useRef<(HTMLInputElement | null)[]>([]);
  const [searching, setSearching] = useState(false);
  const [searchError, setSearchError] = useState<string | null>(null);

  // ── State résultat ────────────────────────────────────────────────
  const [booking, setBooking] = useState<BookingFound | null>(null);
  const [actionLoading, setActionLoading] = useState(false);
  const [actionError, setActionError] = useState<string | null>(null);
  const [actionSuccess, setActionSuccess] = useState<BookingStatut | null>(null);

  // ── Historique du jour ────────────────────────────────────────────
  const [history, setHistory] = useState<HistoryEntry[]>([]);
  const [historyLoading, setHistoryLoading] = useState(true);

  // ── Stats du jour ─────────────────────────────────────────────────
  const todayPaye = history.filter((h) => h.statut === "confirme").length;
  const todayCA = history
    .filter((h) => h.statut === "confirme")
    .reduce((s, h) => s + h.service_prix, 0);

  // ── Focus auto au montage ─────────────────────────────────────────
  useEffect(() => {
    setTimeout(() => inputRefs.current[0]?.focus(), 300);
  }, []);

  // ── Chargement historique ─────────────────────────────────────────
  const loadHistory = useCallback(async () => {
    if (!institutionId) return;
    setHistoryLoading(true);
    const today = new Date().toISOString().slice(0, 10);

    const { data } = await supabase
      .from("paid_bookings")
      .select(
        `
        id, confirmation_code, statut, date_rdv, heure_rdv,
        paid_services!inner(nom, prix),
        users!paid_bookings_citoyen_id_fkey(prenom, nom)
      `
      )
      .eq("institution_id", institutionId)
      .eq("date_rdv", today)
      .neq("statut", "en_attente")
      .order("created_at", { ascending: false });

    if (data) {
      setHistory(
        (data as unknown as BookingRow[]).map((row) => ({
          id: row.id,
          confirmation_code: row.confirmation_code,
          statut: row.statut,
          date_rdv: row.date_rdv,
          heure_rdv: row.heure_rdv,
          service_nom: row.paid_services?.nom ?? "Service",
          service_prix: row.paid_services?.prix ?? 0,
          validated_at: null,
          citoyen_nom: row.users
            ? `${row.users.prenom ?? ""} ${row.users.nom ?? ""}`.trim() || null
            : null,
        }))
      );
    }
    setHistoryLoading(false);
  }, [institutionId]);

  useEffect(() => {
    loadHistory();
  }, [loadHistory]);

  // ── Gestion saisie code ───────────────────────────────────────────
  function handleDigit(index: number, value: string) {
    const v = value.replace(/\D/g, "").slice(-1);
    const next = [...digits];
    next[index] = v;
    setDigits(next);
    setSearchError(null);
    if (v && index < 5) {
      inputRefs.current[index + 1]?.focus();
    }
  }

  function handleKeyDown(index: number, e: React.KeyboardEvent<HTMLInputElement>) {
    if (e.key === "Backspace" && !digits[index] && index > 0) {
      inputRefs.current[index - 1]?.focus();
    }
    if (e.key === "Enter" && digits.every((d) => d !== "")) {
      handleSearch();
    }
  }

  function handlePaste(e: React.ClipboardEvent<HTMLInputElement>) {
    const pasted = e.clipboardData.getData("text").replace(/\D/g, "").slice(0, 6);
    if (pasted.length === 6) {
      setDigits(pasted.split(""));
      setTimeout(() => inputRefs.current[5]?.focus(), 10);
    }
  }

  function resetCode() {
    setDigits(["", "", "", "", "", ""]);
    setBooking(null);
    setSearchError(null);
    setActionError(null);
    setActionSuccess(null);
    setTimeout(() => inputRefs.current[0]?.focus(), 50);
  }

  // ── Recherche ─────────────────────────────────────────────────────
  const handleSearch = useCallback(async () => {
    const code = digits.join("");
    if (code.length !== 6) {
      setSearchError("Veuillez saisir les 6 chiffres du code Yelen.");
      return;
    }
    setSearching(true);
    setSearchError(null);
    setBooking(null);
    setActionSuccess(null);
    setActionError(null);

    const { data, error } = await supabase
      .from("paid_bookings")
      .select(
        `
        id, confirmation_code, statut, date_rdv, heure_rdv,
        paid_services!inner(nom, prix, duree_minutes),
        users!paid_bookings_citoyen_id_fkey(prenom, nom, phone)
      `
      )
      .eq("confirmation_code", code)
      .eq("institution_id", institutionId)
      .maybeSingle();

    setSearching(false);

    if (error) {
      setSearchError("Erreur lors de la recherche : " + error.message);
      return;
    }
    if (!data) {
      setSearchError(
        "Aucune réservation trouvée pour ce code dans votre institution. Vérifiez le code et réessayez."
      );
      return;
    }

    const row = data as unknown as BookingRow;
    setBooking({
      id: row.id,
      confirmation_code: row.confirmation_code,
      statut: row.statut,
      date_rdv: row.date_rdv,
      heure_rdv: row.heure_rdv,
      pour_autre: false,
      nom_autre: null,
      phone_autre: null,
      service_nom: row.paid_services?.nom ?? "Service",
      service_prix: row.paid_services?.prix ?? 0,
      service_duree: row.paid_services?.duree_minutes ?? 0,
      citoyen_prenom: row.users?.prenom ?? null,
      citoyen_nom: row.users?.nom ?? null,
      citoyen_phone: row.users?.phone ?? null,
      citoyen_email: null,
    });
  }, [digits, institutionId]);

  // ── Actions ───────────────────────────────────────────────────────
  async function handleAction(newStatut: BookingStatut) {
    if (!booking) return;
    setActionLoading(true);
    setActionError(null);

    const updateData: Record<string, unknown> = { statut: newStatut };

    const { error: bkErr } = await supabase
      .from("paid_bookings")
      .update(updateData)
      .eq("id", booking.id);

    if (bkErr) {
      setActionError("Erreur lors de la mise à jour : " + bkErr.message);
      setActionLoading(false);
      return;
    }

    // Mise à jour table rdv en parallèle (best effort)
    const rdvStatut =
      newStatut === "confirme"
        ? "confirme"
        : newStatut === "annule"
        ? "annule"
        : "no_show";

    await supabase
      .from("rdv")
      .update({ statut: rdvStatut })
      .eq("qr_token", booking.confirmation_code)
      .eq("institution_id", institutionId);

    setActionSuccess(newStatut);
    setBooking((prev) => (prev ? { ...prev, statut: newStatut } : null));
    setActionLoading(false);
    loadHistory();
  }

  // ── CSS global ────────────────────────────────────────────────────
  const CSS = `
    *{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
    html,body{overflow-x:hidden;background:${C.pageBg}}
    ::-webkit-scrollbar{display:none}
    *{scrollbar-width:none}
    @keyframes spin{to{transform:rotate(360deg)}}
    @keyframes fadeUp{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}
    @keyframes popIn{from{opacity:0;transform:scale(0.93)}to{opacity:1;transform:scale(1)}}
    @keyframes pulse{0%,100%{opacity:1}50%{opacity:0.5}}
    .tap{transition:opacity .1s,transform .1s;cursor:pointer;touch-action:manipulation}
    .tap:active{opacity:0.65;transform:scale(0.97)}
    input:focus{outline:none}
    .digit-input{
      width:44px;height:58px;border-radius:14px;
      font-size:26px;font-weight:900;text-align:center;
      font-family:'SF Mono',monospace;
      transition:all 0.15s;
      caret-color:transparent;
    }
    .digit-input:focus{
      border-color:#F5A623 !important;
      box-shadow:0 0 0 3px rgba(245,166,35,0.22) !important;
      transform:scale(1.08);
    }
    .btn-primary{
      padding:17px;border-radius:16px;border:none;
      background:linear-gradient(135deg,#F5A623,#C8940A);
      color:#080812;font-size:14px;font-weight:800;
      display:flex;align-items:center;justify-content:center;gap:8px;
      box-shadow:0 6px 20px rgba(245,166,35,0.38);
      transition:all 0.2s;width:100%;
    }
    .btn-primary:disabled{
      background:${isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.06)"};
      color:${C.textSubtle};box-shadow:none;cursor:not-allowed;
    }
    .guide-step{
      display:flex;align-items:flex-start;gap:10px;
      padding:10px 0;
      border-bottom:1px solid ${isDark ? "rgba(255,255,255,0.04)" : "rgba(0,0,0,0.04)"};
    }
    .guide-step:last-child{border-bottom:none}
  `;

  const inputBg = isDark ? "rgba(255,255,255,0.04)" : "rgba(0,0,0,0.03)";
  const inputBord = isDark ? "rgba(255,255,255,0.1)" : "rgba(0,0,0,0.1)";
  const codeComplete = digits.every((d) => d !== "");

  return (
    <div
      style={{
        minHeight: "100svh",
        backgroundColor: C.pageBg,
        fontFamily: "'SF Pro Text',-apple-system,'Helvetica Neue',sans-serif",
        color: C.text,
        paddingBottom: "80px",
      }}
    >
      <style>{CSS}</style>

      {/* ════ HEADER ════ */}
      <div
        style={{
          position: "sticky",
          top: 0,
          zIndex: 100,
          backgroundColor: isDark ? "rgba(8,8,15,0.97)" : "rgba(248,248,251,0.97)",
          backdropFilter: "blur(20px)",
          WebkitBackdropFilter: "blur(20px)",
          borderBottom: `1px solid ${
            isDark ? "rgba(245,166,35,0.12)" : "rgba(245,166,35,0.15)"
          }`,
        }}
      >
        <div
          style={{
            height: "3px",
            background: "linear-gradient(90deg,#F5A623,#C8940A,#F5A623)",
          }}
        />
        <div
          style={{
            padding: "12px 16px",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
          }}
        >
          <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
            <Link
              href={`/institution/${institutionId}/dashboard`}
              style={{
                width: "34px",
                height: "34px",
                borderRadius: "10px",
                background: isDark ? "rgba(255,255,255,0.05)" : "rgba(0,0,0,0.05)",
                border: `1px solid ${inputBord}`,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                textDecoration: "none",
                flexShrink: 0,
              }}
            >
              <svg
                width="16"
                height="16"
                viewBox="0 0 24 24"
                fill="none"
                stroke={C.textSubtle}
                strokeWidth="2.5"
                strokeLinecap="round"
              >
                <polyline points="15 18 9 12 15 6" />
              </svg>
            </Link>
            <div>
              <div
                style={{
                  color: C.text,
                  fontSize: "15px",
                  fontWeight: "900",
                  letterSpacing: "-0.3px",
                }}
              >
                Valider un paiement
              </div>
              <div
                style={{
                  color: "#F5A623",
                  fontSize: "9px",
                  fontWeight: "700",
                  letterSpacing: "1.5px",
                }}
              >
                YELEN224 · CAISSE INSTITUTION
              </div>
            </div>
          </div>

          {/* Stats rapides */}
          <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
            <div
              style={{
                padding: "5px 10px",
                background: "rgba(0,200,150,0.1)",
                border: "1px solid rgba(0,200,150,0.2)",
                borderRadius: "20px",
                textAlign: "center",
              }}
            >
              <div
                style={{ color: "#00C896", fontSize: "14px", fontWeight: "900" }}
              >
                {todayPaye}
              </div>
              <div
                style={{
                  color: "#00C896",
                  fontSize: "8px",
                  fontWeight: "700",
                  opacity: 0.75,
                }}
              >
                payés
              </div>
            </div>
            <div
              style={{
                padding: "5px 10px",
                background: "rgba(245,166,35,0.08)",
                border: "1px solid rgba(245,166,35,0.2)",
                borderRadius: "20px",
                textAlign: "center",
                maxWidth: "90px",
              }}
            >
              <div
                style={{
                  color: "#F5A623",
                  fontSize: "10px",
                  fontWeight: "900",
                  whiteSpace: "nowrap",
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                }}
              >
                {formatPrix(todayCA)}
              </div>
              <div
                style={{
                  color: "#F5A623",
                  fontSize: "8px",
                  fontWeight: "700",
                  opacity: 0.7,
                }}
              >
                aujourd&apos;hui
              </div>
            </div>
          </div>
        </div>
      </div>

      <div style={{ maxWidth: "520px", margin: "0 auto", padding: "20px 16px 0" }}>

        {/* ════ GUIDE D'UTILISATION ════ */}
        {!booking && (
          <div
            style={{
              marginBottom: "18px",
              padding: "16px 18px",
              background: isDark
                ? "rgba(245,166,35,0.04)"
                : "rgba(245,166,35,0.03)",
              border: `1px solid ${
                isDark ? "rgba(245,166,35,0.1)" : "rgba(245,166,35,0.15)"
              }`,
              borderRadius: "18px",
              animation: "fadeUp 0.35s ease",
            }}
          >
            <div
              style={{
                color: C.textSubtle,
                fontSize: "9px",
                fontWeight: "700",
                letterSpacing: "1.4px",
                textTransform: "uppercase",
                marginBottom: "12px",
              }}
            >
              📋 Comment valider un paiement
            </div>
            {[
              {
                num: "1",
                title: "Le citoyen se présente au guichet",
                desc: "Il ouvre son application Yelen224 et affiche son code à 6 chiffres.",
              },
              {
                num: "2",
                title: "Saisissez le code ci-dessous",
                desc: "Entrez les 6 chiffres du code Yelen affiché sur son téléphone.",
              },
              {
                num: "3",
                title: "Vérifiez la fiche et encaissez",
                desc: "Confirmez le service, le montant, puis cliquez sur « Valider le paiement ».",
              },
            ].map((step) => (
              <div key={step.num} className="guide-step">
                <div
                  style={{
                    width: "22px",
                    height: "22px",
                    borderRadius: "7px",
                    background: "rgba(245,166,35,0.12)",
                    border: "1px solid rgba(245,166,35,0.2)",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    color: "#F5A623",
                    fontSize: "11px",
                    fontWeight: "900",
                    flexShrink: 0,
                    marginTop: "1px",
                  }}
                >
                  {step.num}
                </div>
                <div>
                  <div
                    style={{
                      color: C.text,
                      fontSize: "12px",
                      fontWeight: "700",
                      marginBottom: "2px",
                    }}
                  >
                    {step.title}
                  </div>
                  <div
                    style={{
                      color: C.textSubtle,
                      fontSize: "11px",
                      lineHeight: 1.5,
                    }}
                  >
                    {step.desc}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* ════ SAISIE CODE ════ */}
        <div
          style={{
            background: C.cardBg,
            borderRadius: "24px",
            border: `1px solid ${
              isDark ? "rgba(245,166,35,0.15)" : "rgba(245,166,35,0.2)"
            }`,
            overflow: "hidden",
            marginBottom: "20px",
            animation: "fadeUp 0.3s ease",
            boxShadow: isDark
              ? "0 8px 40px rgba(0,0,0,0.4)"
              : "0 8px 40px rgba(245,166,35,0.08)",
          }}
        >
          <div
            style={{
              height: "4px",
              background: "linear-gradient(90deg,#F5A623,#F2C94C,#F5A623)",
            }}
          />
          <div style={{ padding: "24px 20px" }}>
            <div style={{ textAlign: "center", marginBottom: "22px" }}>
              <div
                style={{
                  width: "54px",
                  height: "54px",
                  borderRadius: "16px",
                  background: "rgba(245,166,35,0.1)",
                  border: "1.5px solid rgba(245,166,35,0.25)",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  margin: "0 auto 12px",
                }}
              >
                <svg
                  width="24"
                  height="24"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="#F5A623"
                  strokeWidth="2"
                  strokeLinecap="round"
                >
                  <rect x="3" y="11" width="18" height="11" rx="2" />
                  <path d="M7 11V7a5 5 0 0 1 10 0v4" />
                </svg>
              </div>
              <h2
                style={{
                  color: C.text,
                  fontSize: "19px",
                  fontWeight: "900",
                  margin: "0 0 6px",
                  letterSpacing: "-0.4px",
                }}
              >
                Code de confirmation
              </h2>
              <p
                style={{
                  color: C.textSubtle,
                  fontSize: "12px",
                  margin: 0,
                  lineHeight: 1.7,
                }}
              >
                Saisissez le code Yelen à 6 chiffres affiché
                <br />
                sur l&apos;application du citoyen
              </p>
            </div>

            {/* Inputs 6 chiffres */}
            <div
              style={{
                display: "flex",
                justifyContent: "center",
                gap: "7px",
                marginBottom: "10px",
              }}
            >
              {digits.map((d, i) => (
                <div
                  key={i}
                  style={{
                    display: "flex",
                    alignItems: "center",
                  }}
                >
                  <input
                    ref={(el) => {
                      inputRefs.current[i] = el;
                    }}
                    className="digit-input"
                    type="text"
                    inputMode="numeric"
                    maxLength={1}
                    value={d}
                    onChange={(e) => handleDigit(i, e.target.value)}
                    onKeyDown={(e) => handleKeyDown(i, e)}
                    onPaste={i === 0 ? handlePaste : undefined}
                    style={{
                      background: d
                        ? isDark
                          ? "rgba(245,166,35,0.12)"
                          : "rgba(245,166,35,0.08)"
                        : inputBg,
                      border: `2px solid ${
                        d ? "rgba(245,166,35,0.45)" : inputBord
                      }`,
                      color: d ? "#F5A623" : C.textSubtle,
                    }}
                  />
                  {i === 2 && (
                    <div
                      style={{
                        width: "14px",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        color: C.textSubtle,
                        fontSize: "18px",
                        fontWeight: "300",
                        margin: "0 1px",
                        userSelect: "none",
                      }}
                    >
                      –
                    </div>
                  )}
                </div>
              ))}
            </div>

            {/* Indicateur progression */}
            <div
              style={{
                textAlign: "center",
                marginBottom: "16px",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                gap: "8px",
              }}
            >
              <div
                style={{
                  height: "3px",
                  width: "80px",
                  borderRadius: "99px",
                  background: isDark ? "rgba(255,255,255,0.08)" : "rgba(0,0,0,0.07)",
                  overflow: "hidden",
                }}
              >
                <div
                  style={{
                    height: "100%",
                    width: `${(digits.filter((d) => d !== "").length / 6) * 100}%`,
                    background: "linear-gradient(90deg,#F5A623,#C8940A)",
                    transition: "width 0.2s ease",
                    borderRadius: "99px",
                  }}
                />
              </div>
              <span
                style={{
                  color: C.textSubtle,
                  fontSize: "10px",
                  fontWeight: "600",
                }}
              >
                {digits.filter((d) => d !== "").length}/6 chiffres
              </span>
            </div>

            {/* Erreur recherche */}
            {searchError && (
              <div
                style={{
                  marginBottom: "14px",
                  padding: "12px 14px",
                  background: "rgba(255,71,87,0.08)",
                  border: "1px solid rgba(255,71,87,0.2)",
                  borderRadius: "12px",
                  display: "flex",
                  alignItems: "flex-start",
                  gap: "8px",
                  animation: "popIn 0.2s ease",
                }}
              >
                <svg
                  width="14"
                  height="14"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="#FF4757"
                  strokeWidth="2.5"
                  strokeLinecap="round"
                  style={{ flexShrink: 0, marginTop: "1px" }}
                >
                  <circle cx="12" cy="12" r="10" />
                  <line x1="15" y1="9" x2="9" y2="15" />
                  <line x1="9" y1="9" x2="15" y2="15" />
                </svg>
                <span
                  style={{
                    color: "#FF4757",
                    fontSize: "12px",
                    fontWeight: "600",
                    lineHeight: 1.5,
                  }}
                >
                  {searchError}
                </span>
              </div>
            )}

            {/* Boutons */}
            <div
              style={{
                display: "grid",
                gridTemplateColumns: booking ? "1fr 2fr" : "1fr",
                gap: "10px",
              }}
            >
              {booking && (
                <button
                  onClick={resetCode}
                  className="tap"
                  style={{
                    padding: "14px",
                    borderRadius: "14px",
                    border: `1px solid ${inputBord}`,
                    background: inputBg,
                    color: C.textSubtle,
                    fontSize: "13px",
                    fontWeight: "700",
                    cursor: "pointer",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    gap: "6px",
                  }}
                >
                  <svg
                    width="13"
                    height="13"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2.5"
                    strokeLinecap="round"
                  >
                    <polyline points="1 4 1 10 7 10" />
                    <path d="M3.51 15a9 9 0 1 0 .49-4.5" />
                  </svg>
                  Nouveau
                </button>
              )}
              <button
                onClick={handleSearch}
                disabled={searching || !codeComplete}
                className="tap"
                style={{
                  padding: "15px",
                  borderRadius: "14px",
                  border: "none",
                  background: codeComplete
                    ? "linear-gradient(135deg,#F5A623,#C8940A)"
                    : isDark
                    ? "rgba(255,255,255,0.06)"
                    : "rgba(0,0,0,0.06)",
                  color: codeComplete ? "#080812" : C.textSubtle,
                  fontSize: "14px",
                  fontWeight: "800",
                  cursor: codeComplete ? "pointer" : "not-allowed",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  gap: "8px",
                  boxShadow: codeComplete
                    ? "0 6px 20px rgba(245,166,35,0.35)"
                    : "none",
                  transition: "all 0.2s",
                }}
              >
                {searching ? (
                  <>
                    <YelenLoader size={15} color="#080812"/>
                    Recherche en cours…
                  </>
                ) : (
                  <>
                    <svg
                      width="15"
                      height="15"
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="2.5"
                      strokeLinecap="round"
                    >
                      <circle cx="11" cy="11" r="8" />
                      <path d="m21 21-4.35-4.35" />
                    </svg>
                    Rechercher la réservation
                  </>
                )}
              </button>
            </div>
          </div>
        </div>

        {/* ════ FICHE RÉSERVATION ════ */}
        {booking && (
          <div
            style={{ animation: "popIn 0.25s ease", marginBottom: "20px" }}
          >
            {/* Statut déjà traité */}
            {booking.statut !== "en_attente" && !actionSuccess && (
              <div
                style={{
                  marginBottom: "14px",
                  padding: "14px 16px",
                  background: STATUT_CONFIG[booking.statut].bg,
                  border: `1px solid ${STATUT_CONFIG[booking.statut].color}33`,
                  borderRadius: "14px",
                  display: "flex",
                  alignItems: "center",
                  gap: "12px",
                }}
              >
                <span style={{ fontSize: "22px" }}>
                  {STATUT_CONFIG[booking.statut].icon}
                </span>
                <div>
                  <div
                    style={{
                      color: STATUT_CONFIG[booking.statut].color,
                      fontSize: "13px",
                      fontWeight: "800",
                    }}
                  >
                    Cette réservation est déjà :{" "}
                    {STATUT_CONFIG[booking.statut].label}
                  </div>
                  <div
                    style={{
                      color: C.textSubtle,
                      fontSize: "11px",
                      marginTop: "3px",
                      lineHeight: 1.5,
                    }}
                  >
                    Elle a déjà été traitée. Aucune action supplémentaire
                    n&apos;est requise.
                  </div>
                </div>
              </div>
            )}

            {/* Succès action */}
            {actionSuccess && (
              <div
                style={{
                  marginBottom: "14px",
                  padding: "20px 16px",
                  background: STATUT_CONFIG[actionSuccess].bg,
                  border: `2px solid ${STATUT_CONFIG[actionSuccess].color}44`,
                  borderRadius: "18px",
                  textAlign: "center",
                  animation: "popIn 0.3s ease",
                }}
              >
                <div style={{ fontSize: "36px", marginBottom: "8px" }}>
                  {STATUT_CONFIG[actionSuccess].icon}
                </div>
                <div
                  style={{
                    color: STATUT_CONFIG[actionSuccess].color,
                    fontSize: "17px",
                    fontWeight: "900",
                    letterSpacing: "-0.3px",
                  }}
                >
                  {actionSuccess === "confirme" && "Paiement validé avec succès !"}
                  {actionSuccess === "no_show" && "Citoyen marqué absent"}
                  {actionSuccess === "annule" && "Réservation annulée"}
                </div>
                {actionSuccess === "confirme" && (
                  <div
                    style={{
                      color: C.textSubtle,
                      fontSize: "12px",
                      marginTop: "6px",
                      lineHeight: 1.6,
                    }}
                  >
                    {formatPrix(booking.service_prix)} encaissé en espèces
                    <br />
                    {new Date().toLocaleTimeString("fr-FR", {
                      hour: "2-digit",
                      minute: "2-digit",
                    })}{" "}
                    — Historique mis à jour
                  </div>
                )}
              </div>
            )}

            {/* Carte réservation */}
            <div
              style={{
                background: C.cardBg,
                borderRadius: "22px",
                border: `1.5px solid ${
                  booking.statut === "en_attente"
                    ? "rgba(245,166,35,0.3)"
                    : isDark
                    ? "rgba(255,255,255,0.08)"
                    : "rgba(0,0,0,0.08)"
                }`,
                overflow: "hidden",
                boxShadow: isDark
                  ? "0 8px 40px rgba(0,0,0,0.4)"
                  : "0 8px 40px rgba(245,166,35,0.1)",
              }}
            >
              <div
                style={{
                  height: "4px",
                  background:
                    booking.statut === "en_attente"
                      ? "linear-gradient(90deg,#F5A623,#F2C94C)"
                      : STATUT_CONFIG[booking.statut].color,
                }}
              />
              <div style={{ padding: "20px" }}>

                {/* En-tête code + statut */}
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    marginBottom: "18px",
                  }}
                >
                  <div>
                    <div
                      style={{
                        color: C.textSubtle,
                        fontSize: "9px",
                        fontWeight: "700",
                        letterSpacing: "1.5px",
                        textTransform: "uppercase",
                        marginBottom: "6px",
                      }}
                    >
                      Code Yelen
                    </div>
                    <div style={{ display: "flex", gap: "3px" }}>
                      {booking.confirmation_code.split("").map((c, i) => (
                        <div
                          key={i}
                          style={{
                            width: "28px",
                            height: "36px",
                            borderRadius: "8px",
                            background: isDark
                              ? "rgba(245,166,35,0.1)"
                              : "rgba(245,166,35,0.07)",
                            border: "1px solid rgba(245,166,35,0.2)",
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "center",
                            color: "#F5A623",
                            fontSize: "17px",
                            fontWeight: "900",
                            fontFamily: "monospace",
                          }}
                        >
                          {c}
                        </div>
                      ))}
                    </div>
                  </div>
                  <div
                    style={{
                      padding: "6px 12px",
                      background: STATUT_CONFIG[booking.statut].bg,
                      border: `1px solid ${STATUT_CONFIG[booking.statut].color}44`,
                      borderRadius: "20px",
                    }}
                  >
                    <span
                      style={{
                        color: STATUT_CONFIG[booking.statut].color,
                        fontSize: "11px",
                        fontWeight: "800",
                      }}
                    >
                      {STATUT_CONFIG[booking.statut].label}
                    </span>
                  </div>
                </div>

                {/* Service */}
                <div
                  style={{
                    padding: "14px 16px",
                    background: isDark
                      ? "rgba(245,166,35,0.06)"
                      : "rgba(245,166,35,0.04)",
                    border: "1px solid rgba(245,166,35,0.15)",
                    borderRadius: "14px",
                    marginBottom: "12px",
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "space-between",
                    }}
                  >
                    <div style={{ flex: 1, minWidth: 0, paddingRight: "12px" }}>
                      <div
                        style={{
                          color: C.textSubtle,
                          fontSize: "9px",
                          fontWeight: "700",
                          letterSpacing: "1px",
                          textTransform: "uppercase",
                          marginBottom: "4px",
                        }}
                      >
                        Service réservé
                      </div>
                      <div
                        style={{
                          color: C.text,
                          fontSize: "15px",
                          fontWeight: "800",
                          marginBottom: "3px",
                        }}
                      >
                        {booking.service_nom}
                      </div>
                      <div
                        style={{
                          color: C.textSubtle,
                          fontSize: "11px",
                          lineHeight: 1.5,
                        }}
                      >
                        {booking.service_duree > 0
                          ? `${booking.service_duree} min · `
                          : ""}
                        {formatDate(booking.date_rdv, booking.heure_rdv)}
                      </div>
                    </div>
                    <div style={{ textAlign: "right", flexShrink: 0 }}>
                      <div
                        style={{
                          color: C.textSubtle,
                          fontSize: "9px",
                          fontWeight: "700",
                          letterSpacing: "1px",
                          textTransform: "uppercase",
                          marginBottom: "4px",
                        }}
                      >
                        Montant dû
                      </div>
                      <div
                        style={{
                          color: "#F5A623",
                          fontSize: "20px",
                          fontWeight: "900",
                          letterSpacing: "-0.5px",
                        }}
                      >
                        {formatPrix(booking.service_prix)}
                      </div>
                      <div
                        style={{
                          color: C.textSubtle,
                          fontSize: "10px",
                          fontWeight: "600",
                          marginTop: "2px",
                        }}
                      >
                        💵 Espèces
                      </div>
                    </div>
                  </div>
                </div>

                {/* Citoyen */}
                <div
                  style={{
                    padding: "14px 16px",
                    background: inputBg,
                    border: `1px solid ${inputBord}`,
                    borderRadius: "14px",
                    marginBottom:
                      booking.statut === "en_attente" && !actionSuccess
                        ? "20px"
                        : "0",
                  }}
                >
                  <div
                    style={{
                      color: C.textSubtle,
                      fontSize: "9px",
                      fontWeight: "700",
                      letterSpacing: "1px",
                      textTransform: "uppercase",
                      marginBottom: "10px",
                    }}
                  >
                    {booking.pour_autre ? "👤 Bénéficiaire (tiers)" : "👤 Citoyen"}
                  </div>
                  {booking.pour_autre && booking.nom_autre ? (
                    <div
                      style={{
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "space-between",
                      }}
                    >
                      <div>
                        <div
                          style={{
                            color: C.text,
                            fontSize: "14px",
                            fontWeight: "800",
                          }}
                        >
                          {booking.nom_autre}
                        </div>
                        {booking.phone_autre && (
                          <div
                            style={{
                              color: C.textSubtle,
                              fontSize: "12px",
                              marginTop: "3px",
                            }}
                          >
                            {booking.phone_autre}
                          </div>
                        )}
                      </div>
                      <div
                        style={{
                          padding: "4px 10px",
                          background: "rgba(245,166,35,0.08)",
                          border: "1px solid rgba(245,166,35,0.2)",
                          borderRadius: "20px",
                        }}
                      >
                        <span
                          style={{
                            color: "#F5A623",
                            fontSize: "10px",
                            fontWeight: "700",
                          }}
                        >
                          Tiers
                        </span>
                      </div>
                    </div>
                  ) : (
                    <div
                      style={{
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "space-between",
                      }}
                    >
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div
                          style={{
                            color: C.text,
                            fontSize: "14px",
                            fontWeight: "800",
                            marginBottom: "3px",
                          }}
                        >
                          {booking.citoyen_prenom || booking.citoyen_nom
                            ? `${booking.citoyen_prenom ?? ""} ${
                                booking.citoyen_nom ?? ""
                              }`.trim()
                            : "Citoyen enregistré"}
                        </div>
                        {booking.citoyen_phone && (
                          <div
                            style={{
                              color: C.textSubtle,
                              fontSize: "12px",
                              marginTop: "2px",
                            }}
                          >
                            📱 {booking.citoyen_phone}
                          </div>
                        )}
                      </div>
                      {booking.citoyen_phone && (
                        <a
                          href={`tel:${booking.citoyen_phone}`}
                          style={{
                            width: "36px",
                            height: "36px",
                            borderRadius: "11px",
                            background: "rgba(245,166,35,0.1)",
                            border: "1px solid rgba(245,166,35,0.2)",
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "center",
                            textDecoration: "none",
                            flexShrink: 0,
                            marginLeft: "10px",
                          }}
                        >
                          <svg
                            width="14"
                            height="14"
                            viewBox="0 0 24 24"
                            fill="none"
                            stroke="#F5A623"
                            strokeWidth="2.5"
                            strokeLinecap="round"
                          >
                            <path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07A19.5 19.5 0 0 1 4.69 13a19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 3.54 2h3a2 2 0 0 1 2 1.72c.127.96.361 1.903.7 2.81a2 2 0 0 1-.45 2.11L7.91 9.91a16 16 0 0 0 6.16 6.16l1.27-1.27a2 2 0 0 1 2.11-.45c.907.339 1.85.573 2.81.7A2 2 0 0 1 22 16.92z" />
                          </svg>
                        </a>
                      )}
                    </div>
                  )}
                </div>

                {/* ── Boutons actions — uniquement si en_attente ── */}
                {booking.statut === "en_attente" && !actionSuccess && (
                  <div
                    style={{
                      display: "flex",
                      flexDirection: "column",
                      gap: "10px",
                    }}
                  >
                    {actionError && (
                      <div
                        style={{
                          padding: "11px 14px",
                          background: "rgba(255,71,87,0.08)",
                          border: "1px solid rgba(255,71,87,0.2)",
                          borderRadius: "12px",
                          color: "#FF4757",
                          fontSize: "12px",
                          fontWeight: "600",
                          lineHeight: 1.5,
                        }}
                      >
                        ⚠️ {actionError}
                      </div>
                    )}

                    {/* CTA principal — Valider paiement */}
                    <button
                      onClick={() => handleAction("confirme")}
                      disabled={actionLoading}
                      className="tap"
                      style={{
                        padding: "19px",
                        borderRadius: "16px",
                        border: "none",
                        background: actionLoading
                          ? isDark
                            ? "rgba(255,255,255,0.06)"
                            : "rgba(0,0,0,0.06)"
                          : "linear-gradient(135deg,#00C896,#00A07A)",
                        color: actionLoading ? C.textSubtle : "#fff",
                        fontSize: "16px",
                        fontWeight: "900",
                        cursor: actionLoading ? "not-allowed" : "pointer",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        gap: "10px",
                        boxShadow: actionLoading
                          ? "none"
                          : "0 8px 28px rgba(0,200,150,0.4)",
                        letterSpacing: "-0.3px",
                        transition: "all 0.2s",
                      }}
                    >
                      {actionLoading ? (
                        <>
                          <YelenLoader size={16} color="#fff"/>
                          Traitement en cours…
                        </>
                      ) : (
                        <>
                          <svg
                            width="18"
