            </div>
          </div>
        )}

        {/* ════ HISTORIQUE DU JOUR ════ */}
        <div style={{ animation: "fadeUp 0.4s ease 0.1s both" }}>
          <div
            style={{
              display: "flex",
              alignItems: "center",
