                      </div>
                      <div
                        style={{
                          display: "flex",
                          alignItems: "center",
                          gap: "6px",
                        }}
                      >
                        <span
                          style={{
                            color: C.textSubtle,
                            fontSize: "10px",
                            fontFamily: "monospace",
                            fontWeight: "700",
                            background: isDark
                              ? "rgba(255,255,255,0.05)"
                              : "rgba(0,0,0,0.04)",
                            padding: "1px 6px",
                            borderRadius: "4px",
                          }}
                        >
                          {entry.confirmation_code}
                        </span>
                        {entry.citoyen_nom && (
                          <span
                            style={{
                              color: C.textSubtle,
                              fontSize: "10px",
                              overflow: "hidden",
                              textOverflow: "ellipsis",
                              whiteSpace: "nowrap",
                            }}
                          >
                            · {entry.citoyen_nom}
                          </span>
                        )}
                        {entry.validated_at && (
                          <span
                            style={{
                              color: C.textSubtle,
                              fontSize: "10px",
                              marginLeft: "auto",
                              flexShrink: 0,
                            }}
                          >
                            {formatTime(entry.validated_at)}
