                    </div>
                  </div>
                );
              })}
            </div>
          )}

          {/* ── Total CA du jour ── */}
          {history.length > 0 && (
            <div
              style={{
                marginTop: "14px",
                padding: "16px 18px",
                background: isDark
                  ? "rgba(0,200,150,0.06)"
                  : "rgba(0,200,150,0.04)",
                border: "1px solid rgba(0,200,150,0.2)",
                borderRadius: "16px",
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
              }}
            >
              <div>
                <div
                  style={{
                    color: C.textSubtle,
                    fontSize: "10px",
                    fontWeight: "700",
                    textTransform: "uppercase",
                    letterSpacing: "0.8px",
                    marginBottom: "4px",
                  }}
                >
                  Total encaissé aujourd&apos;hui
                </div>
                <div
                  style={{
                    color: "#00C896",
                    fontSize: "22px",
                    fontWeight: "900",
                    letterSpacing: "-0.5px",
                  }}
                >
                  {formatPrix(todayCA)}
                </div>
              </div>
              <div style={{ textAlign: "right" }}>
                <div
                  style={{
                    color: C.textSubtle,
                    fontSize: "10px",
                    fontWeight: "700",
                    textTransform: "uppercase",
                    letterSpacing: "0.8px",
                    marginBottom: "4px",
                  }}
                >
                  Réservations
                </div>
                <div
                  style={{
                    fontSize: "16px",
                    fontWeight: "900",
                  }}
                >
                  <span style={{ color: "#00C896" }}>{todayPaye}</span>
                  <span
                    style={{ color: C.textSubtle, fontSize: "12px" }}
                  >
                    {" "}
                    / {history.length}
                  </span>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

