async function ft<T>(p: Promise<T> | PromiseLike<T>, ms = 5000): Promise<T | null> {
  try {
    return await Promise.race([
      p,
      new Promise<never>((_, r) => setTimeout(() => r(new Error("timeout")), ms))
    ]);
  } catch { return null; }
}

