              enfants={
                <div style={{ display: "flex", flexDirection: "column", gap: "8px", maxWidth: "260px", margin: "0 auto" }}>
                  <button onClick={() => setQuery("")} className="ro-tap" style={{ padding: "11px", borderRadius: "12px", border: "none", background: "linear-gradient(135deg,#F5A623,#C8940A)", color: "#080812", fontWeight: "800", fontSize: "13px" }}>Explorer les catégories</button>
                  {meilleuresNotes.length > 0 && (
                    <button onClick={() => commit("")} className="ro-tap" style={{ padding: "11px", borderRadius: "12px", border: `1px solid ${brd}`, background: "none", color: C.text, fontWeight: "700", fontSize: "13px" }}>Voir les établissements populaires</button>
                  )}
                </div>
              }
            />
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: "26px" }}>
              {etablissementsTrouves.length > 0 && (
                <SectionResultats titre="Établissements" C={C} t2={t2} onVoirTout={() => commit(query)} labelVoirTout="Voir tout">
                  <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
                    {etablissementsTrouves.slice(0, 6).map(inst => (
                      <div key={inst.id} className="ro-card"><CarteInstitutionCard inst={inst} C={C} t2={t2} citoyenGeoloc={citoyenGeoloc} estFavori={favorisIdsSet.has(inst.id)} onToggleFavori={e => { e.stopPropagation(); onToggleFavori(inst); }} onSelect={() => { commit(query); window.location.href = `/institution/${inst.id}`; }}/></div>
                    ))}
                  </div>
                </SectionResultats>
              )}

              {servicesTrouves.length > 0 && (
                <SectionResultats titre="Services" C={C} t2={t2}>
                  <div style={{ display: "flex", flexDirection: "column", gap: "8px" }}>
                    {servicesTrouves.map((s, i) => (
                      <a key={`${s.instId}-${i}`} href={`/institution/${s.instId}`} onClick={() => commit(query)} className="ro-tap ro-card" style={{ display: "flex", alignItems: "center", gap: "10px", padding: "10px", background: C.cardBg, border: `1px solid ${brd}`, borderRadius: "14px", textDecoration: "none" }}>
                        <InstitutionLogo inst={{ id: s.instId, name: s.instName, category: s.instCategory, logo: s.instLogo } as Institution} size={38}/>
                        <div style={{ flex: 1, minWidth: 0 }}>
                          <div style={{ color: C.text, fontSize: "13px", fontWeight: "800", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{s.nom}</div>
                          <div style={{ color: t2, fontSize: "11px", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{s.instName}{s.duree_minutes ? ` · ${s.duree_minutes} min` : ""}</div>
                        </div>
                        {s.prix != null && <div style={{ color: "#F5A623", fontSize: "12px", fontWeight: "800", flexShrink: 0 }}>{s.prix.toLocaleString("fr-FR")} GNF</div>}
                      </a>
                    ))}
                  </div>
                </SectionResultats>
              )}

              {categoriesTrouvees.length > 0 && (
                <SectionResultats titre="Catégories" C={C} t2={t2} onVoirTout={() => onApplyCategorie(categoriesTrouvees[0][0])} labelVoirTout="Explorer">
                  <div style={{ display: "flex", gap: "8px", flexWrap: "wrap" }}>
                    {categoriesTrouvees.map(([key, meta]) => (
                      <button key={key} onClick={() => onApplyCategorie(key)} className="ro-tap ro-card" style={{ display: "flex", alignItems: "center", gap: "7px", padding: "9px 14px", borderRadius: "20px", border: `1px solid ${brd}`, background: C.cardBg, cursor: "pointer" }}>
                        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#F5A623" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d={meta.svgPath}/></svg>
                        <span style={{ color: C.text, fontSize: "12.5px", fontWeight: "800" }}>{meta.short}</span>
                      </button>
                    ))}
                  </div>
                </SectionResultats>
              )}

              {offresTrouvees.length > 0 && (
                <SectionResultats titre="Offres" C={C} t2={t2}>
                  <div className="no-scroll" style={{ overflowX: "auto" }}>
                    <div style={{ display: "flex", gap: "10px", width: "max-content" }}>
                      {offresTrouvees.slice(0, 8).map(o => (
                        <a key={o.id} href={`/offres/${o.id}`} className="ro-tap ro-card" style={{ width: "180px", flexShrink: 0, textDecoration: "none", background: C.cardBg, border: `1px solid ${brd}`, borderRadius: "16px", overflow: "hidden" }}>
                          {o.image_url && <div style={{ height: "90px", background: C.sectionAlt }}><img src={o.image_url} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }}/></div>}
                          <div style={{ padding: "10px" }}>
                            <div style={{ color: C.text, fontSize: "12.5px", fontWeight: "800", lineHeight: 1.3, marginBottom: "4px", display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical" as const, overflow: "hidden" }}>{o.titre}</div>
                            {o.partenaire_nom && <div style={{ color: t2, fontSize: "10.5px" }}>{o.partenaire_nom}</div>}
                            <div style={{ marginTop: "8px", color: "#F5A623", fontSize: "11px", fontWeight: "800" }}>Découvrir →</div>
                          </div>
                        </a>
                      ))}
                    </div>
                  </div>
                </SectionResultats>
              )}

              {recommandations.length > 0 && (
                <SectionResultats titre="Recommandations" sousTitre={secteurTopLabel ? `Basé sur vos rendez-vous en ${secteurTopLabel.toLowerCase()}` : undefined} C={C} t2={t2}>
                  <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
                    {recommandations.map(inst => (
                      <div key={inst.id} className="ro-card"><CarteInstitutionCard inst={inst} C={C} t2={t2} citoyenGeoloc={citoyenGeoloc} estFavori={favorisIdsSet.has(inst.id)} onToggleFavori={e => { e.stopPropagation(); onToggleFavori(inst); }} onSelect={() => { commit(query); window.location.href = `/institution/${inst.id}`; }}/></div>
                    ))}
                  </div>
                </SectionResultats>
              )}
            </div>
          )
        ) : premiereFois ? (
          <EtatVide
            variante="premiere-fois" C={C} t2={t2}
            titre="Commencez votre première recherche"
            description="Recherchez une institution, un service ou une entreprise."
            enfants={
              <button onClick={() => inputRef.current?.focus()} className="ro-tap" style={{ padding: "11px 22px", borderRadius: "12px", border: "none", background: "linear-gradient(135deg,#F5A623,#C8940A)", color: "#080812", fontWeight: "800", fontSize: "13px" }}>Explorer</button>
            }
          />
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "26px" }}>
            {recherchesRecentes.length > 0 && (
              <section>
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: "10px" }}>
                  <div style={{ color: C.text, fontSize: "14px", fontWeight: "800" }}>Recherches récentes</div>
