                      <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#080812" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d={meta.svgPath}/></svg>
                    </div>
                    <span style={{ color: C.text, fontSize: "11.5px", fontWeight: "800", textAlign: "center" }}>{meta.short}</span>
