export function CategorieBadge({ categorie, taille = 32 }: { categorie: string; taille?: number }) {
  const c = categorie as PostCategorie;
  const couleur = POST_CATEGORIE_COULEURS[c] || "#8E8E93";
  const glyphe = CATEGORIE_GLYPHES[c];
  return (
    <div style={{ width: taille, height: taille, borderRadius: "50%", flexShrink: 0, background: `${couleur}22`, display: "flex", alignItems: "center", justifyContent: "center" }}>
      <svg width={taille * 0.52} height={taille * 0.52} viewBox="0 0 24 24" fill="none" stroke={couleur} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <path d={glyphe} />
      </svg>
    </div>
  );
}

export function CategorieChip({ categorie, actif, onClick, texteCouleur }: { categorie: string; actif?: boolean; onClick?: () => void; texteCouleur: string }) {
  const c = categorie as PostCategorie;
  const couleur = POST_CATEGORIE_COULEURS[c] || "#8E8E93";
  const label = POST_CATEGORIE_LABELS[c] || categorie;
  return (
    <button onClick={onClick} className="tap" style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: "6px", background: "none", border: "none", cursor: onClick ? "pointer" : "default", padding: 0, flexShrink: 0, width: "64px" }}>
      <div style={{ boxShadow: actif ? `0 0 0 2px ${couleur}` : "none", borderRadius: "50%" }}>
        <CategorieBadge categorie={categorie} taille={44} />
      </div>
      <span style={{ color: actif ? couleur : texteCouleur, fontSize: "10px", fontWeight: actif ? 800 : 600, textAlign: "center", lineHeight: 1.2 }}>{label}</span>
    </button>
  );
}

export function PostCard({
  post, isDark, card, t1, t2, t3, brd,
  liked, likeCount, commentCount, onToggleLike, onPartager,
  commentsOuverts, onToggleComments, commentairesListe, commentDraft, onChangeCommentDraft, onSubmitComment,
  onOpenAuteur, onSignalerPost, onSignalerAuteur,
}: {
  post: Post; isDark: boolean; card: string; t1: string; t2: string; t3: string; brd: string;
  liked: boolean; likeCount: number; commentCount: number;
  onToggleLike: () => void; onPartager: () => void;
  commentsOuverts: boolean; onToggleComments: () => void;
  commentairesListe: Commentaire[] | undefined;
  commentDraft: string; onChangeCommentDraft: (v: string) => void; onSubmitComment: () => void;
  onOpenAuteur: () => void; onSignalerPost: () => void; onSignalerAuteur: () => void;
}) {
  const [menuOuvert, setMenuOuvert] = useState(false);
  const couleurCat = POST_CATEGORIE_COULEURS[post.categorie as PostCategorie];
  const labelCat = POST_CATEGORIE_LABELS[post.categorie as PostCategorie];

  return (
    <div style={{ background: card, border: `1px solid ${brd}`, borderRadius: "16px", padding: "16px" }}>
      <div style={{ display: "flex", alignItems: "flex-start", gap: "6px", marginBottom: "10px" }}>
        <button onClick={onOpenAuteur} className="tap" style={{ display: "flex", alignItems: "center", gap: "10px", flex: 1, minWidth: 0, background: "none", border: "none", padding: 0, cursor: "pointer", textAlign: "left" }}>
          <Avatar nom={post.author_nom} photo={post.author_photo_url} taille={40} />
          <div style={{ minWidth: 0 }}>
            <div style={{ display: "flex", alignItems: "center", gap: "6px" }}>
              <span style={{ color: t1, fontSize: "13.5px", fontWeight: 800, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{post.author_nom}</span>
              {post.author_verifie && <BadgeVerifie />}
            </div>
            <div style={{ color: t2, fontSize: "11px" }}>
              Membre de Yelen depuis {formatDateFr(post.author_membre_depuis)}
            </div>
          </div>
        </button>
        <div style={{ position: "relative", flexShrink: 0 }}>
          <button onClick={() => setMenuOuvert(o => !o)} aria-label="Options" className="tap" style={{ width: "28px", height: "28px", borderRadius: "50%", background: "none", border: "none", display: "flex", alignItems: "center", justifyContent: "center", color: t3, cursor: "pointer" }}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><circle cx="12" cy="5" r="1.6" /><circle cx="12" cy="12" r="1.6" /><circle cx="12" cy="19" r="1.6" /></svg>
          </button>
          {menuOuvert && (
            <>
              <div onClick={() => setMenuOuvert(false)} style={{ position: "fixed", inset: 0, zIndex: 4 }} />
              <div style={{ position: "absolute", top: "100%", right: 0, zIndex: 5, background: card, border: `1px solid ${brd}`, borderRadius: "12px", boxShadow: "0 8px 24px rgba(0,0,0,0.18)", padding: "6px", minWidth: "200px" }}>
                <button onClick={() => { setMenuOuvert(false); onSignalerPost(); }} className="tap" style={{ display: "block", width: "100%", textAlign: "left", background: "none", border: "none", padding: "9px 10px", borderRadius: "8px", color: t1, fontSize: "12.5px", fontWeight: 700, cursor: "pointer" }}>
                  Signaler cette publication
                </button>
                <button onClick={() => { setMenuOuvert(false); onSignalerAuteur(); }} className="tap" style={{ display: "block", width: "100%", textAlign: "left", background: "none", border: "none", padding: "9px 10px", borderRadius: "8px", color: "#ef4444", fontSize: "12.5px", fontWeight: 700, cursor: "pointer" }}>
                  Signaler {post.author_nom}
                </button>
              </div>
            </>
          )}
        </div>
      </div>

      {couleurCat && (
        <span style={{ display: "inline-block", background: `${couleurCat}18`, color: couleurCat, fontSize: "10px", fontWeight: 800, padding: "3px 9px", borderRadius: "20px", marginBottom: "10px" }}>{labelCat}</span>
      )}

      {post.contenu && <div style={{ color: t1, fontSize: "13.5px", lineHeight: 1.6, whiteSpace: "pre-wrap", marginBottom: post.images?.length ? "10px" : "12px" }}>{post.contenu}</div>}

      {post.images && post.images.length > 0 && (
        <div style={{ display: "grid", gridTemplateColumns: post.images.length === 1 ? "1fr" : "1fr 1fr", gap: "6px", marginBottom: "12px", borderRadius: "12px", overflow: "hidden" }}>
          {post.images.map((url, i) => (
            <img key={i} src={url} alt="" style={{ width: "100%", height: post.images!.length === 1 ? "auto" : "140px", maxHeight: "320px", objectFit: "cover" }} />
          ))}
        </div>
      )}

      <div style={{ display: "flex", alignItems: "center", gap: "18px", paddingTop: "10px", borderTop: `1px solid ${brd}` }}>
        <button onClick={onToggleLike} className="tap" style={{ display: "flex", alignItems: "center", gap: "6px", background: "none", border: "none", color: liked ? "#F5A623" : t2, fontSize: "12.5px", fontWeight: 700, cursor: "pointer", padding: 0 }}>
          <svg width="17" height="17" viewBox="0 0 24 24" fill={liked ? "#F5A623" : "none"} stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M14 9V5a3 3 0 0 0-3-3l-4 9v11h11.28a2 2 0 0 0 2-1.7l1.38-9a2 2 0 0 0-2-2.3zM7 22H4a2 2 0 0 1-2-2v-7a2 2 0 0 1 2-2h3" /></svg>
          {likeCount > 0 ? likeCount : ""}
        </button>
        <button onClick={onToggleComments} className="tap" style={{ display: "flex", alignItems: "center", gap: "6px", background: "none", border: "none", color: commentsOuverts ? t1 : t2, fontSize: "12.5px", fontWeight: 700, cursor: "pointer", padding: 0 }}>
          <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z" /></svg>
          {commentCount > 0 ? commentCount : ""}
        </button>
        <button onClick={onPartager} className="tap" style={{ display: "flex", alignItems: "center", gap: "6px", background: "none", border: "none", color: t2, fontSize: "12.5px", fontWeight: 700, cursor: "pointer", padding: 0 }}>
          <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="18" cy="5" r="3" /><circle cx="6" cy="12" r="3" /><circle cx="18" cy="19" r="3" /><line x1="8.6" y1="13.5" x2="15.4" y2="17.5" /><line x1="15.4" y1="6.5" x2="8.6" y2="10.5" /></svg>
          {post.nb_partages > 0 ? post.nb_partages : ""}
        </button>
        <span style={{ marginLeft: "auto", color: t3, fontSize: "11px" }}>{tempsRelatif(post.created_at)}</span>
      </div>

      {commentsOuverts && (
        <div style={{ marginTop: "12px", paddingTop: "12px", borderTop: `1px solid ${brd}` }}>
          {commentairesListe === undefined ? (
            <div style={{ display: "flex", justifyContent: "center", padding: "10px" }}><YelenLoader size={16} color={t2} /></div>
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: "10px", marginBottom: "10px" }}>
              {commentairesListe.map(c => (
                <div key={c.id} style={{ display: "flex", gap: "8px" }}>
                  <Avatar nom={c.citoyen_nom} photo={c.citoyen_photo_url} taille={26} />
                  <div style={{ background: isDark ? "rgba(255,255,255,0.04)" : "rgba(0,0,0,0.03)", borderRadius: "12px", padding: "8px 12px", flex: 1 }}>
                    <div style={{ color: t1, fontSize: "12px", fontWeight: 800, marginBottom: "2px" }}>{c.citoyen_nom}</div>
                    <div style={{ color: t2, fontSize: "12.5px", lineHeight: 1.5 }}>{c.contenu}</div>
                  </div>
                </div>
              ))}
              {commentairesListe.length === 0 && <div style={{ color: t3, fontSize: "12px", textAlign: "center" }}>Aucun commentaire pour l&apos;instant.</div>}
            </div>
          )}
          <div style={{ display: "flex", gap: "8px" }}>
            <input
              value={commentDraft}
              onChange={e => onChangeCommentDraft(e.target.value)}
              onKeyDown={e => { if (e.key === "Enter" && commentDraft.trim()) onSubmitComment(); }}
              placeholder="Écrire un commentaire…"
              style={{ flex: 1, background: isDark ? "rgba(255,255,255,0.05)" : "rgba(0,0,0,0.04)", border: "none", borderRadius: "20px", padding: "9px 14px", color: t1, fontSize: "12.5px", outline: "none" }}
            />
            <button onClick={onSubmitComment} disabled={!commentDraft.trim()} className="tap" style={{ background: "none", border: "none", color: commentDraft.trim() ? "#F5A623" : t3, cursor: commentDraft.trim() ? "pointer" : "default", padding: "4px 6px" }}>
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="22" y1="2" x2="11" y2="13" /><polygon points="22 2 15 22 11 13 2 9 22 2" /></svg>
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

// Création d'une publication "Yelen Community" en plein écran (27/07/2026,
// retour Bryan : "mettons la création en pop pleine comme les profils")
// — même convention header que ProfilAuteurOverlay/OffreFicheOverlay (X +
// titre centré), remplace l'ancien composeur qui s'étendait en ligne dans
// le fil.
import { Avatar, CategorieChip } from "@/components/CommunautePostCard";
import { YelenLoader } from "@/components/YelenLoader";
import { POST_CATEGORIES } from "@/lib/communauteCategories";

const MAX_IMAGES = 4;

export default function CreerPostOverlay({
  userName, userPhoto,
  texte, setTexte, fichiers, setFichiers, categorie, setCategorie, envoi,
  fileInputRef, onChoisirFichiers, onPublier, onFermer,
  isDark, bg, card2, t1, t2, brd,
}: {
  userName: string; userPhoto: string | null;
  texte: string; setTexte: (v: string) => void;
  fichiers: File[]; setFichiers: (v: File[] | ((prev: File[]) => File[])) => void;
  categorie: string | null; setCategorie: (v: string) => void;
  envoi: boolean;
  fileInputRef: React.RefObject<HTMLInputElement | null>;
  onChoisirFichiers: (f: FileList | null) => void;
  onPublier: () => void;
  onFermer: () => void;
  isDark: boolean; bg: string; card: string; card2: string; t1: string; t2: string; brd: string;
}) {
  const peutPublier = (texte.trim() || fichiers.length > 0) && categorie && !envoi;

  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 1000, background: bg, display: "flex", flexDirection: "column" }}>
      <header style={{ position: "sticky", top: 0, zIndex: 1, background: bg, borderBottom: `1px solid ${brd}`, paddingTop: "env(safe-area-inset-top)", flexShrink: 0 }}>
        <div style={{ padding: "12px 16px", display: "grid", gridTemplateColumns: "1fr auto 1fr", alignItems: "center", gap: "12px" }}>
          <button onClick={onFermer} className="tap" aria-label="Fermer" style={{ justifySelf: "start", width: "36px", height: "36px", borderRadius: "50%", background: card2, border: `1px solid ${brd}`, display: "flex", alignItems: "center", justifyContent: "center", color: t1, cursor: "pointer" }}>
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round"><line x1="18" y1="6" x2="6" y2="18" /><line x1="6" y1="6" x2="18" y2="18" /></svg>
          </button>
          <div style={{ color: t1, fontSize: "16px", fontWeight: 800, textAlign: "center" }}>Nouvelle publication</div>
          <button
            onClick={onPublier}
            disabled={!peutPublier}
            className="tap"
            style={{ justifySelf: "end", display: "flex", alignItems: "center", gap: "6px", background: "linear-gradient(135deg,#F5A623,#C8940A)", border: "none", borderRadius: "10px", padding: "9px 16px", color: "#080812", fontSize: "13px", fontWeight: 800, cursor: peutPublier ? "pointer" : "default", opacity: peutPublier ? 1 : 0.5 }}
          >
            {envoi ? <YelenLoader size={14} color="#080812" /> : "Publier"}
          </button>
        </div>
      </header>

      <main style={{ flex: 1, overflowY: "auto", padding: "16px 20px 40px", width: "100%", maxWidth: "560px", margin: "0 auto", boxSizing: "border-box" }}>
        <div style={{ display: "flex", alignItems: "center", gap: "10px", marginBottom: "14px" }}>
          <Avatar nom={userName} photo={userPhoto} taille={40} />
          <span style={{ color: t1, fontSize: "14px", fontWeight: 800 }}>{userName}</span>
        </div>

        <textarea
          autoFocus
          value={texte}
          onChange={e => setTexte(e.target.value)}
          placeholder="Partagez une idée, une expérience professionnelle…"
          style={{ width: "100%", minHeight: "140px", background: "none", border: "none", outline: "none", color: t1, fontSize: "15px", fontFamily: "inherit", resize: "vertical", boxSizing: "border-box", marginBottom: "14px" }}
        />

        {fichiers.length > 0 && (
          <div style={{ display: "flex", gap: "8px", flexWrap: "wrap", marginBottom: "16px" }}>
            {fichiers.map((f, i) => (
              <div key={i} style={{ position: "relative", width: "76px", height: "76px", borderRadius: "12px", overflow: "hidden", border: `1px solid ${brd}` }}>
                <img src={URL.createObjectURL(f)} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                <button onClick={() => setFichiers(prev => prev.filter((_, idx) => idx !== i))} aria-label="Retirer" className="tap" style={{ position: "absolute", top: "3px", right: "3px", width: "20px", height: "20px", borderRadius: "50%", background: "rgba(0,0,0,0.6)", border: "none", color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}>
                  <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3.4" strokeLinecap="round"><line x1="18" y1="6" x2="6" y2="18" /><line x1="6" y1="6" x2="18" y2="18" /></svg>
                </button>
              </div>
            ))}
          </div>
        )}

        <input ref={fileInputRef} type="file" accept="image/*" multiple hidden onChange={e => onChoisirFichiers(e.target.files)} />
        <button
          onClick={() => fileInputRef.current?.click()}
          disabled={fichiers.length >= MAX_IMAGES}
          className="tap"
          style={{ display: "flex", alignItems: "center", gap: "6px", background: isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.05)", border: "none", borderRadius: "10px", padding: "9px 14px", color: t2, fontSize: "12.5px", fontWeight: 700, cursor: fichiers.length >= MAX_IMAGES ? "default" : "pointer", opacity: fichiers.length >= MAX_IMAGES ? 0.5 : 1, marginBottom: "22px" }}
        >
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" /><circle cx="8.5" cy="8.5" r="1.5" /><path d="M21 15l-5-5L5 21" /></svg>
          Ajouter une image ({fichiers.length}/{MAX_IMAGES})
        </button>

        {/* Catégorie — obligatoire, max 10, jamais politique/race/ethnie. */}
        <div>
          <div style={{ color: t2, fontSize: "10.5px", fontWeight: 800, textTransform: "uppercase", letterSpacing: "0.4px", marginBottom: "10px" }}>
            Catégorie {!categorie && <span style={{ color: "#ef4444" }}>· requise</span>}
          </div>
          <div style={{ display: "flex", gap: "14px", overflowX: "auto", paddingBottom: "6px" }}>
            {POST_CATEGORIES.map(cat => (
              <CategorieChip key={cat} categorie={cat} actif={categorie === cat} onClick={() => setCategorie(cat)} texteCouleur={t2} />
            ))}
          </div>
        </div>
      </main>
    </div>
  );
}

"use client";

import Link from "next/link";
import { useState, useEffect, type ReactNode, type MouseEvent as ReactMouseEvent } from "react";
import { institutionsRecentes, retirerInstitutionRecente, type InstitutionRecente } from "@/lib/institutionsRecentes";

// Cartes-événement optionnelles affichées à la suite de la grille des
// établissements récemment consultés (retour Bryan 29/07/2026 — dépenses à
// venir). Format volontairement différent des tuiles logo/institution (qui
// n'ont de sens que pour un vrai logo carré) : une carte plus large,
// horizontale, avec assez de place pour un montant + un libellé + une
// échéance — un logo écrasé sur 50px n'aurait pas la place de rester lisible
// pour ce type de contenu (retour Bryan : "sa dois afficher en horizontal
// pas logo comme pour les institutions consultées"). Gérées par le parent
// (visibilité + retrait) car leur condition d'affichage dépend de données
// réelles hors du périmètre de ce composant. Chaque carte a son propre
// retrait (X sur l'une n'affecte pas les autres) ; la section entière
// disparaît seulement quand établissements récents ET cartes événement sont
// tous les deux vides.
export type TuileExtra = { key: string; href: string; icon: ReactNode; titre: string; sousTexte: string; accentColor: string; onDismiss: () => void };

// Établissements récemment consultés — façon Booking.com "Continue your
// search" (retour Bryan 25/07/2026). Grille de 5 par ligne (passe à une 2e
// ligne au-delà), X pour retirer un établissement — le revisiter le
// réinsère naturellement, pas de liste noire séparée à gérer.
// Extrait de app/page.tsx (26/07/2026) pour être réutilisé par
// app/compte/recherche/recherche-client.tsx sans dupliquer la logique.
// Titre "Votre exploration | Vos dépenses" (retour Bryan 29/07/2026) — les
// deux familles de contenu (établissements récents, dépenses à venir)
// partagent désormais une seule rangée de défilement horizontal, donc un
// seul titre couvrant les deux plutôt que "Continuez votre exploration" qui
// ne décrivait plus que la moitié du contenu.
export function InstitutionsRecentesSection({ isDark, t1, t2, card, brd, extraTiles }: { isDark: boolean; t1: string; t2: string; card: string; brd: string; extraTiles?: TuileExtra[] }) {
  const [items, setItems] = useState<InstitutionRecente[]>([]);
  const tuiles = extraTiles ?? [];

  useEffect(() => { setItems(institutionsRecentes()); }, []);

  if (items.length === 0 && tuiles.length === 0) return null;

  function handleRemove(e: ReactMouseEvent, id: string) {
    e.preventDefault();
    e.stopPropagation();
    setItems(retirerInstitutionRecente(id));
  }

  return (
    <div style={{ padding: "16px 16px 0" }}>
      <div style={{ color: t1, fontSize: "14px", fontWeight: "800", marginBottom: "10px" }}>Votre exploration | Vos dépenses</div>

      <div style={{ display: "flex", alignItems: "flex-start", gap: "10px", overflowX: "auto", paddingBottom: "2px" }}>
        {items.map(inst => (
          <Link key={inst.id} href={`/institution/${inst.id}`} className="tap" style={{ textDecoration: "none", flexShrink: 0, width: "64px", display: "flex", flexDirection: "column", alignItems: "center", position: "relative" }}>
            <button onClick={e => handleRemove(e, inst.id)} aria-label="Retirer" style={{ position: "absolute", top: "-4px", right: "2px", zIndex: 1, width: "18px", height: "18px", borderRadius: "50%", background: isDark ? "#2C2C2E" : "#fff", border: `1px solid ${brd}`, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", padding: 0, boxShadow: "0 1px 4px rgba(0,0,0,0.15)" }}>
              <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke={t2} strokeWidth="3" strokeLinecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
            </button>
            <div style={{ width: "50px", height: "50px", borderRadius: "16px", overflow: "hidden", background: card, border: `1px solid ${brd}`, display: "flex", alignItems: "center", justifyContent: "center", marginBottom: "5px" }}>
              {inst.logo ? (
                <img src={inst.logo} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }}/>
              ) : (
                <span style={{ color: t2, fontSize: "15px", fontWeight: "900" }}>{inst.name.slice(0, 2).toUpperCase()}</span>
              )}
            </div>
            <span style={{ color: t1, fontSize: "10px", fontWeight: "700", textAlign: "center", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", maxWidth: "56px" }}>{inst.name}</span>
          </Link>
        ))}
        {tuiles.map(t => (
          <Link key={t.key} href={t.href} className="tap" style={{ textDecoration: "none", flexShrink: 0, width: "168px" }}>
            <div style={{ position: "relative", backgroundColor: card, borderRadius: "14px", padding: "12px 14px", border: `1px solid ${brd}`, borderLeftWidth: "3px", borderLeftColor: t.accentColor }}>
              <button
                onClick={e => { e.preventDefault(); e.stopPropagation(); t.onDismiss(); }}
                aria-label="Retirer"
                style={{ position: "absolute", top: "8px", right: "8px", width: "18px", height: "18px", borderRadius: "50%", background: isDark ? "#2C2C2E" : "#fff", border: `1px solid ${brd}`, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", padding: 0, boxShadow: "0 1px 4px rgba(0,0,0,0.15)" }}
              >
                <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke={t2} strokeWidth="3" strokeLinecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
              </button>
              <div style={{ marginBottom: "8px" }}>{t.icon}</div>
              <div style={{ color: t1, fontSize: "13.5px", fontWeight: "900", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", paddingRight: "18px" }}>{t.titre}</div>
              <div style={{ color: t2, fontSize: "10.5px", fontWeight: "700", marginTop: "2px", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{t.sousTexte}</div>
            </div>
          </Link>
        ))}
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { useRouter } from "next/navigation";
import { supabase } from "@/lib/supabase";
import { useTheme } from "@/components/ThemeProvider";
import {
  calculerMinutesAvantRdv, determinerEtat, messageProchainRdv,
  MESSAGE_AVIS_ATTENTE, MESSAGE_ANNONCE, MESSAGE_VIDE,
  MESSAGE_DOCUMENT_ATTENTE, MESSAGE_DEMARCHE_RETARD, MESSAGE_DEMARCHE_ECHEANCE,
} from "@/lib/assistantMessages";

// ============================================================
// "Mon Assistant" — bandeau tirable (bottom sheet), écran Accueil citoyen.
// Voir CLAUDE.md /chantier-mon-assistant pour le brief produit complet.
//
// Mécanique de glissement écrite à la main (pointer events) — aucune
// librairie de gestes n'existe dans ce projet (vérifié, package.json).
// Le `<div>` racine garde une position fixe (bottom = hauteur nav +
// safe-area), sa `height` anime entre COLLAPSED_H et une hauteur max
// plafonnée sous le header (calc CSS, jamais de z-index seul) — z-index
// 90, sous la nav du bas (100) et le header (100), donc jamais par-dessus.
// ============================================================

type InstitutionLite = { id: string; name: string; category: string; logo: string | null } | null;
type RdvLite = { id: string; date_rdv: string; heure_rdv: string; objet: string | null; statut: string; institutions: InstitutionLite };
type AnnonceLite = { id: string; titre: string; contenu: string; type: string; format: string | null; media_urls: string[] | null; image_url: string | null; created_at: string; date_expiration: string | null; institutions: InstitutionLite };
type DemarcheLite = { id: string; titre: string };
type DocumentAttenteLite = { id: string; label: string; institutions: InstitutionLite };

const COLLAPSED_H = 68;
const NAV_H = 78; // hauteur approx. de la <nav> bas (paddingTop 10 + contenu ~48 + paddingBottom 8), avant safe-area
const HEADER_CLEARANCE = 110; // marge de sécurité sous le header pour le calc CSS du max-height
const DRAG_SNAP_RATIO = 0.35; // fraction de la course pour basculer d'état au relâchement

const Ic = {
  Grip:     () => <div style={{ width: "36px", height: "4px", borderRadius: "2px", background: "currentColor", opacity: 0.35, margin: "0 auto" }}/>,
  Cal:      () => <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>,
  Star:     () => <svg width="16" height="16" viewBox="0 0 24 24" fill="#F5A623" stroke="#F5A623" strokeWidth="1.5"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>,
  Announce: () => <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 11v2a1 1 0 0 0 1 1h1l3.6 5.4a1 1 0 0 0 1.7-.9L9.5 14H17a4 4 0 0 0 0-8H4a1 1 0 0 0-1 1z"/><path d="M15 6v12"/></svg>,
  Doc:      () => <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>,
  Clock:    () => <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round"><circle cx="12" cy="12" r="9"/><polyline points="12 7 12 12 16 14"/></svg>,
  Sparkle:  ({ size = 40 }: { size?: number }) => <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"><path d="M12 3v4M12 17v4M3 12h4M17 12h4M6.5 6.5l2 2M15.5 15.5l2 2M6.5 17.5l2-2M15.5 8.5l2-2"/><circle cx="12" cy="12" r="3"/></svg>,
  Chev:     () => <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><polyline points="9 18 15 12 9 6"/></svg>,
  X:        () => <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>,
};

const ASSISTANT_DISMISS_KEY = "yelen224_assistant_dismissed_until";

function InstitutionAvatar({ logo, name, size = 22 }: { logo: string | null | undefined; name: string; size?: number }) {
  const initiales = name.split(" ").slice(0, 2).map((w) => w[0]?.toUpperCase() || "").join("") || "?";
  if (logo) {
    return <img src={logo} alt="" style={{ width: size, height: size, borderRadius: "50%", objectFit: "cover", flexShrink: 0 }} onError={(e) => { (e.target as HTMLImageElement).style.display = "none"; }}/>;
  }
  return (
    <div style={{ width: size, height: size, borderRadius: "50%", background: "linear-gradient(135deg,#F5A623,#C8940A)", color: "#080812", fontSize: size * 0.4, fontWeight: "900", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
      {initiales}
    </div>
  );
}

function formatDateCourte(dateISO: string): string {
  const d = new Date(`${dateISO}T00:00:00`);
  const aujourdhui = new Date(); aujourdhui.setHours(0, 0, 0, 0);
  const demain = new Date(aujourdhui); demain.setDate(demain.getDate() + 1);
  if (d.getTime() === aujourdhui.getTime()) return "aujourd'hui";
  if (d.getTime() === demain.getTime()) return "demain";
  return d.toLocaleDateString("fr-FR", { day: "numeric", month: "short" });
}

export function MonAssistant({ userId }: { userId: string | null }) {
  const router = useRouter();
  const { theme } = useTheme();
  const isDark = theme === "dark";
  const card  = isDark ? "#17171C" : "#FFFFFF";
  const card2 = isDark ? "#232328" : "#F2F2F5";
  const t1    = isDark ? "#FFFFFF" : "#000000";
  const t2    = isDark ? "#9999A6" : "#5A5A63";
  const t3    = isDark ? "#636366" : "#AEAEB2";
  const brd   = isDark ? "rgba(255,255,255,0.08)" : "rgba(0,0,0,0.07)";

  const [upcoming, setUpcoming] = useState<RdvLite[]>([]);
  const [avisAttente, setAvisAttente] = useState<RdvLite[]>([]);
  const [annonces, setAnnonces] = useState<AnnonceLite[]>([]);
  const [demarchesEnRetard, setDemarchesEnRetard] = useState<DemarcheLite[]>([]);
  const [demarchesEcheanceProche, setDemarchesEcheanceProche] = useState<DemarcheLite[]>([]);
  const [documentsAttente, setDocumentsAttente] = useState<DocumentAttenteLite[]>([]);
  const [loaded, setLoaded] = useState(false);
  const [expanded, setExpanded] = useState(false);
  const [nowTick, setNowTick] = useState(() => Date.now());
  // X + popup explicatif (retour Bryan 23/07/2026) — fermer n'efface pas
  // définitivement le bandeau, ça ouvre d'abord un message expliquant sa
  // valeur ; seul le bouton "Masquer 24h" du popup le cache réellement,
  // et seulement temporairement (localStorage, pas de compte à rebours
  // serveur nécessaire pour ce genre de préférence purement locale).
  const [showInfoPopup, setShowInfoPopup] = useState(false);
  const [dismissedUntil, setDismissedUntil] = useState(0);

  useEffect(() => {
    try {
      const raw = localStorage.getItem(ASSISTANT_DISMISS_KEY);
      if (raw) setDismissedUntil(Number(raw) || 0);
    } catch {}
  }, []);

  function handleMasquer24h() {
    const until = Date.now() + 24 * 60 * 60 * 1000;
    try { localStorage.setItem(ASSISTANT_DISMISS_KEY, String(until)); } catch {}
    setDismissedUntil(until);
    setShowInfoPopup(false);
  }

  const panelRef = useRef<HTMLDivElement | null>(null);
  const dragging = useRef<{ startY: number; startH: number } | null>(null);

  const charger = useCallback(async () => {
    if (!userId) return;
    const { data: { session } } = await supabase.auth.getSession();
    if (!session?.access_token) return;
    try {
      const res = await fetch("/api/citoyen/assistant", { headers: { Authorization: `Bearer ${session.access_token}` } });
      const json = await res.json().catch(() => null);
      if (res.ok && json?.success) {
        setUpcoming(json.upcoming ?? []);
        setAvisAttente(json.avisAttente ?? []);
        setAnnonces(json.annonces ?? []);
        setDemarchesEnRetard(json.demarchesEnRetard ?? []);
        setDemarchesEcheanceProche(json.demarchesEcheanceProche ?? []);
        setDocumentsAttente(json.documentsAttente ?? []);
      }
    } catch {}
    setLoaded(true);
  }, [userId]);

  useEffect(() => { void charger(); }, [charger]);

  // Recalcule le message contextuel toutes les 30s (pas de refetch réseau)
  // — même pattern que JournalTab.tsx côté institution — pour que le
  // message change à l'approche du RDV sans dépendre du Realtime (Realtime
  // live hors scope de ce lot, voir plan).
  useEffect(() => {
    const t = setInterval(() => setNowTick(Date.now()), 30000);
    return () => clearInterval(t);
  }, []);

  const setPanelHeight = (h: number, animate: boolean) => {
    const el = panelRef.current;
    if (!el) return;
    el.style.transition = animate ? "height 0.32s cubic-bezier(0.16,1,0.3,1)" : "none";
    el.style.height = `${h}px`;
  };

  const getMaxH = () => {
    if (typeof window === "undefined") return 400;
    return Math.max(COLLAPSED_H, window.innerHeight - HEADER_CLEARANCE - NAV_H);
  };

  useEffect(() => {
    setPanelHeight(expanded ? getMaxH() : COLLAPSED_H, true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [expanded]);

  const onPointerDown = (e: React.PointerEvent) => {
    const el = panelRef.current;
    if (!el) return;
    (e.target as HTMLElement).setPointerCapture?.(e.pointerId);
    dragging.current = { startY: e.clientY, startH: el.getBoundingClientRect().height };
  };
  const onPointerMove = (e: React.PointerEvent) => {
    if (!dragging.current) return;
    const delta = dragging.current.startY - e.clientY; // tirer vers le haut = positif
    const h = Math.min(getMaxH(), Math.max(COLLAPSED_H, dragging.current.startH + delta));
    setPanelHeight(h, false);
  };
  const onPointerUp = () => {
    if (!dragging.current) return;
    const el = panelRef.current;
    const currentH = el ? el.getBoundingClientRect().height : COLLAPSED_H;
    const maxH = getMaxH();
    const seuil = COLLAPSED_H + (maxH - COLLAPSED_H) * DRAG_SNAP_RATIO;
    dragging.current = null;
    setExpanded(currentH >= seuil);
  };
  const onGripTap = () => setExpanded((v) => !v);

  if (!userId || !loaded) return null;
  if (dismissedUntil > nowTick) return null;

  // ── Message contextuel de la position réduite ──
  const now = new Date(nowTick);
  let sommaire = MESSAGE_VIDE;
  if (upcoming.length > 0 && upcoming[0].institutions) {
    const r = upcoming[0];
    const etat = determinerEtat(calculerMinutesAvantRdv({ dateRdv: r.date_rdv, heureRdv: r.heure_rdv, institutionNom: r.institutions!.name }, now), formatDateCourte(r.date_rdv) === "aujourd'hui");
    sommaire = messageProchainRdv(etat, { dateRdv: r.date_rdv, heureRdv: r.heure_rdv, institutionNom: r.institutions!.name }, formatDateCourte(r.date_rdv));
  } else if (documentsAttente.length > 0) {
    sommaire = MESSAGE_DOCUMENT_ATTENTE(documentsAttente.length);
  } else if (demarchesEnRetard.length > 0) {
    sommaire = MESSAGE_DEMARCHE_RETARD(demarchesEnRetard.length);
  } else if (avisAttente.length > 0) {
    sommaire = MESSAGE_AVIS_ATTENTE(avisAttente.length);
  } else if (demarchesEcheanceProche.length > 0) {
    sommaire = MESSAGE_DEMARCHE_ECHEANCE(demarchesEcheanceProche.length);
  } else if (annonces.length > 0) {
    sommaire = MESSAGE_ANNONCE(annonces.length);
  }

  const rien = upcoming.length === 0 && avisAttente.length === 0 && annonces.length === 0
    && demarchesEnRetard.length === 0 && demarchesEcheanceProche.length === 0 && documentsAttente.length === 0;

  return (
    <div
      ref={panelRef}
      style={{
        position: "fixed",
        left: 0, right: 0,
        bottom: `calc(${NAV_H}px + env(safe-area-inset-bottom))`,
        height: `${COLLAPSED_H}px`,
        maxHeight: `calc(100svh - ${HEADER_CLEARANCE}px - ${NAV_H}px)`,
        zIndex: 90,
        background: card,
        borderTop: `1px solid ${brd}`,
        borderRadius: "18px 18px 0 0",
        boxShadow: isDark ? "0 -6px 24px rgba(0,0,0,0.35)" : "0 -6px 24px rgba(0,0,0,0.10)",
        overflow: "hidden",
        display: "flex",
        flexDirection: "column",
        touchAction: "none",
      }}
    >
      {/* Poignée — tap ou glisser (pointer events) */}
      <div
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerUp}
        onClick={onGripTap}
        style={{ flexShrink: 0, padding: "10px 16px 8px", cursor: "grab", color: t2 }}
      >
        <Ic.Grip/>
        <div style={{ display: "flex", alignItems: "center", gap: "8px", marginTop: "10px" }}>
          <div style={{ width: "30px", height: "30px", borderRadius: "9px", background: "#fff", border: `1px solid ${brd}`, color: "#080812", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
            <Ic.Sparkle size={16}/>
          </div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ color: t3, fontSize: "10px", fontWeight: "800", letterSpacing: "0.4px", textTransform: "uppercase" }}>Mon Assistant</div>
            <div style={{ color: t1, fontSize: "13px", fontWeight: "700", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{sommaire}</div>
          </div>
          <button onClick={(e) => { e.stopPropagation(); setShowInfoPopup(true); }} className="tap" style={{ background: "none", border: "none", padding: "6px", margin: "-6px", cursor: "pointer", color: t3, flexShrink: 0, display: "flex" }}><Ic.X/></button>
          <div style={{ transform: expanded ? "rotate(90deg)" : "rotate(-90deg)", transition: "transform 0.25s", color: t3, flexShrink: 0 }}><Ic.Chev/></div>
        </div>
      </div>

      {/* Popup explicatif — ouvert par le X, explique la valeur avant de
          proposer de masquer (retour Bryan 23/07/2026). Rendu via portail
          dans document.body : le panneau racine de Mon Assistant est en
          position:fixed avec son propre z-index (90), ce qui crée un
          contexte d'empilement local — un enfant fixed à l'intérieur ne
          peut jamais dépasser visuellement la nav du bas (z-index 100,
          en dehors de ce contexte) même avec un z-index élevé sur lui-même.
          Le portail sort le popup de ce contexte, comme les autres modales
          de l'app (BiometrieModal, NotifPanel, LogoutFlow) qui n'ont pas
          ce problème car rendues directement au niveau de HomePage. */}
      {showInfoPopup && createPortal(
        <div onClick={() => setShowInfoPopup(false)} style={{ position: "fixed", inset: 0, zIndex: 9500, background: "rgba(0,0,0,0.6)", backdropFilter: "blur(6px)", display: "flex", alignItems: "flex-end", justifyContent: "center" }}>
          <div onClick={(e) => e.stopPropagation()} style={{ background: card, borderRadius: "24px 24px 0 0", padding: "28px 20px calc(20px + env(safe-area-inset-bottom))", width: "100%", maxWidth: "480px" }}>
            <div style={{ width: "56px", height: "56px", borderRadius: "16px", background: "#fff", border: `1px solid ${brd}`, display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 16px", color: "#080812" }}>
              <Ic.Sparkle size={28}/>
            </div>
            <div style={{ color: t1, fontSize: "17px", fontWeight: "800", textAlign: "center", marginBottom: "8px" }}>Mon Assistant</div>
            <div style={{ color: t2, fontSize: "13.5px", lineHeight: 1.6, textAlign: "center", marginBottom: "22px" }}>
              C&apos;est votre assistant personnel pour ne rien manquer sur Yelen : rappels de rendez-vous, documents à fournir, avis à laisser et démarches à surveiller — au bon moment, sans avoir à y penser.
            </div>
            <button onClick={() => setShowInfoPopup(false)} className="tap" style={{ width: "100%", background: "linear-gradient(135deg,#F5A623,#C8940A)", color: "#080812", fontWeight: "800", fontSize: "14px", padding: "13px", borderRadius: "12px", border: "none", cursor: "pointer", marginBottom: "10px" }}>Compris, le garder affiché</button>
            <button onClick={handleMasquer24h} className="tap" style={{ width: "100%", background: "none", color: t2, fontWeight: "700", fontSize: "13px", padding: "10px", borderRadius: "12px", border: "none", cursor: "pointer" }}>Masquer pendant 24h</button>
          </div>
        </div>,
        document.body
      )}

      {/* Contenu déplié — scrollable, jamais responsable de la hauteur du panneau */}
      <div style={{ flex: 1, overflowY: "auto", padding: "4px 16px 20px", display: "flex", flexDirection: "column", gap: "18px" }}>
        {rien ? (
          <div style={{ textAlign: "center", padding: "24px 12px" }}>
            <div style={{ width: "64px", height: "64px", borderRadius: "50%", background: card2, color: "#F5A623", display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 14px" }}>
              <Ic.Sparkle size={30}/>
            </div>
            <div style={{ color: t1, fontSize: "15px", fontWeight: "800", marginBottom: "6px" }}>Mon Assistant est prêt</div>
            <div style={{ color: t2, fontSize: "12.5px", lineHeight: 1.6, maxWidth: "280px", margin: "0 auto" }}>
              Dès votre premier rendez-vous, cet espace vous guidera avant, pendant et après — rappels, préparation, et demandes d&apos;avis, au bon moment.
            </div>
          </div>
        ) : (
          <>
            {upcoming.length > 0 && (
              <Section titre="Prochains rendez-vous" t2={t2}>
                {upcoming.map((r) => (
                  <button key={r.id} onClick={() => router.push("/mes-rdv")} className="tap" style={{ width: "100%", textAlign: "left", display: "flex", alignItems: "center", gap: "10px", background: card2, border: "none", borderRadius: "14px", padding: "12px", cursor: "pointer" }}>
                    <div style={{ width: "34px", height: "34px", borderRadius: "10px", background: "rgba(245,166,35,0.12)", color: "#F5A623", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><Ic.Cal/></div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ color: t1, fontSize: "13px", fontWeight: "800", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{r.institutions?.name ?? "Institution"}</div>
                      <div style={{ color: t2, fontSize: "11.5px", marginTop: "2px" }}>{formatDateCourte(r.date_rdv)} · {r.heure_rdv?.slice(0, 5)}</div>
                    </div>
                  </button>
                ))}
              </Section>
            )}

            {documentsAttente.length > 0 && (
              <Section titre="Documents à fournir" t2={t2}>
                {documentsAttente.map((d) => (
                  <button key={d.id} onClick={() => router.push("/compte/documents-telecharges")} className="tap" style={{ width: "100%", textAlign: "left", display: "flex", alignItems: "center", gap: "10px", background: "rgba(239,68,68,0.06)", border: "1px solid rgba(239,68,68,0.2)", borderRadius: "14px", padding: "12px", cursor: "pointer" }}>
                    <div style={{ width: "34px", height: "34px", borderRadius: "10px", background: "rgba(239,68,68,0.12)", color: "#ef4444", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><Ic.Doc/></div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ color: t1, fontSize: "13px", fontWeight: "800", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{d.label}</div>
                      <div style={{ color: t2, fontSize: "11.5px", marginTop: "2px" }}>{d.institutions?.name ?? "Établissement"} attend ce document</div>
                    </div>
                  </button>
                ))}
              </Section>
            )}

            {avisAttente.length > 0 && (
              <Section titre="Avis à laisser" t2={t2}>
                {avisAttente.map((r) => (
                  <button key={r.id} onClick={() => router.push("/compte/mes-avis")} className="tap" style={{ width: "100%", textAlign: "left", display: "flex", alignItems: "center", gap: "10px", background: "rgba(245,166,35,0.08)", border: "1px solid rgba(245,166,35,0.2)", borderRadius: "14px", padding: "12px", cursor: "pointer" }}>
                    <div style={{ width: "34px", height: "34px", borderRadius: "10px", background: "rgba(245,166,35,0.15)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><Ic.Star/></div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ color: t1, fontSize: "13px", fontWeight: "800" }}>{r.institutions?.name ?? "Institution"}</div>
                      <div style={{ color: "#F5A623", fontSize: "11.5px", marginTop: "2px", fontWeight: "700" }}>Donnez votre avis →</div>
                    </div>
                  </button>
                ))}
              </Section>
            )}

            {(demarchesEnRetard.length > 0 || demarchesEcheanceProche.length > 0) && (
              <Section titre="Démarches à surveiller" t2={t2}>
                {demarchesEnRetard.map((d) => (
                  <button key={d.id} onClick={() => router.push("/compte/mes-demarches")} className="tap" style={{ width: "100%", textAlign: "left", display: "flex", alignItems: "center", gap: "10px", background: "rgba(239,68,68,0.06)", border: "1px solid rgba(239,68,68,0.2)", borderRadius: "14px", padding: "12px", cursor: "pointer" }}>
                    <div style={{ width: "34px", height: "34px", borderRadius: "10px", background: "rgba(239,68,68,0.12)", color: "#ef4444", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><Ic.Clock/></div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ color: t1, fontSize: "13px", fontWeight: "800", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{d.titre}</div>
                      <div style={{ color: "#ef4444", fontSize: "11.5px", marginTop: "2px", fontWeight: "700" }}>En retard</div>
                    </div>
                  </button>
                ))}
                {demarchesEcheanceProche.map((d) => (
                  <button key={d.id} onClick={() => router.push("/compte/mes-demarches")} className="tap" style={{ width: "100%", textAlign: "left", display: "flex", alignItems: "center", gap: "10px", background: card2, border: "none", borderRadius: "14px", padding: "12px", cursor: "pointer" }}>
                    <div style={{ width: "34px", height: "34px", borderRadius: "10px", background: "rgba(245,166,35,0.12)", color: "#F5A623", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><Ic.Clock/></div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ color: t1, fontSize: "13px", fontWeight: "800", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{d.titre}</div>
                      <div style={{ color: t2, fontSize: "11.5px", marginTop: "2px" }}>Échéance cette semaine</div>
                    </div>
                  </button>
                ))}
              </Section>
            )}

            {annonces.length > 0 && (
              <Section titre="Annonces des établissements" t2={t2}>
                {annonces.map((a) => {
                  const nomInst = a.institutions?.name ?? "Institution";
                  const video = !a.image_url && a.format === "video" && a.media_urls?.[0];
                  return (
                    <button key={a.id} onClick={() => a.institutions && router.push(`/institution/${a.institutions.id}`)} className="tap" style={{ width: "100%", textAlign: "left", background: card2, border: `1px solid ${brd}`, borderRadius: "16px", overflow: "hidden", cursor: "pointer", padding: 0 }}>
                      {a.image_url ? (
                        <div style={{ width: "100%", height: "130px", overflow: "hidden", background: card }}>
                          <img src={a.image_url} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} onError={(e) => { (e.target as HTMLImageElement).parentElement!.style.display = "none"; }}/>
                        </div>
                      ) : video ? (
                        <div style={{ width: "100%", height: "150px", overflow: "hidden", background: "#000" }}>
                          <video src={video} style={{ width: "100%", height: "100%", objectFit: "cover" }} muted playsInline preload="metadata"/>
                        </div>
                      ) : null}
                      <div style={{ padding: "12px 14px" }}>
                        <div style={{ display: "flex", alignItems: "center", gap: "8px", marginBottom: "9px" }}>
                          <InstitutionAvatar logo={a.institutions?.logo} name={nomInst} size={22}/>
                          <div style={{ flex: 1, minWidth: 0 }}>
                            <div style={{ color: t1, fontSize: "11.5px", fontWeight: "800", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{nomInst}</div>
                          </div>
                          <span style={{ background: "rgba(59,130,246,0.12)", color: "#3b82f6", fontSize: "9px", fontWeight: "800", padding: "3px 8px", borderRadius: "20px", flexShrink: 0 }}>Annonce</span>
                        </div>
                        <div style={{ color: t1, fontSize: "13.5px", fontWeight: "800", marginBottom: "4px" }}>{a.titre}</div>
                        <div style={{ color: t2, fontSize: "12px", lineHeight: 1.5, overflow: "hidden", textOverflow: "ellipsis", display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical" }}>{a.contenu}</div>
                      </div>
                    </button>
                  );
                })}
              </Section>
            )}
          </>
        )}
      </div>
    </div>
  );
}

function Section({ titre, t2, children }: { titre: string; t2: string; children: React.ReactNode }) {
  return (
    <div>
      <div style={{ color: t2, fontSize: "11px", fontWeight: "800", letterSpacing: "0.3px", textTransform: "uppercase", marginBottom: "8px" }}>{titre}</div>
      <div style={{ display: "flex", flexDirection: "column", gap: "8px" }}>{children}</div>
    </div>
  );
}

"use client";

// Panneau détail d'une offre partenaire (onglet "Offres" de app/page.tsx).
// Refonte niveau US (26/07/2026, référence MoneyLion) : carte de faits,
// preuve sociale honnête (nb_clics réel, jamais inventé), onglets
// Avantages/Limites, description en puces, CTA sticky.
// Passé en overlay plein écran avec header + X (retour Bryan 26/07/2026 :
// même convention que les autres pop du header — CompteRechercheOverlay,
// CitoyenMenu, NotifPanel — plutôt qu'un bottom sheet façon Anthropic).
//
// L'interstitiel "Un instant, direction {partenaire}" (26/07/2026) NE vit
// PAS ici : une première version le montrait dans cet onglet-ci pendant un
// délai avant d'ouvrir un nouvel onglet — bug constaté par Bryan, sur
// mobile l'ouverture d'un nouvel onglet (même vide) fait basculer le focus
// immédiatement, donc l'utilisateur ne voit jamais l'écran affiché dans
// l'onglet qu'il vient de quitter. L'interstitiel est donc rendu
// côté serveur DANS la page de destination elle-même
// (app/api/offres/[id]/clic/route.ts), qui s'ouvre directement au clic
// (geste utilisateur synchrone, jamais bloqué) et ne redirige vers le site
// tiers réel qu'après son propre délai de 3s.
//
// OffreFicheContenu extrait le 02/08/2026 (chantier "Centre de pilotage
// des offres") pour être réutilisé tel quel dans l'aperçu smartphone en
// direct du formulaire de création/édition d'offre
// (MesOffresTab.tsx::draftOffre, visible uniquement dans le pop plein
// écran de création — jamais sur l'écran principal) — zéro changement
// visuel côté citoyen, ce fichier reste un thin wrapper (position fixe + header +
// bouton fermer) autour du contenu.
import { useState } from "react";
import { OFFRE_GENRE_LABELS, OFFRE_GENRE_COULEURS, type OffreGenre } from "@/lib/offresCategories";

export type Fait = { label: string; valeur: string };
export type Offre = {
  id: string;
  titre: string;
  description_courte: string;
  description_longue: string;
  categorie: string;
  genre: string;
  partenaire_nom: string;
  partenaire_logo: string | null;
  image_url?: string | null;
  cta_label: string | null;
  cta_url: string | null;
  date_expiration?: string | null;
  nb_clics?: number;
  faits?: Fait[];
  avantages?: string[];
  limites?: string[];
  // Avis réels de l'établissement (institutions.moyenne_avis/nb_avis) —
  // affiché après le nom, jamais si nb_avis = 0.
  institutions?: { moyenne_avis: number | null; nb_avis: number | null } | null;
};

export function OffreFicheContenu({
  offre, isDark, card, t1, t2, t3, brd, populaire,
}: {
  offre: Offre;
  isDark: boolean;
  card: string;
  t1: string;
  t2: string;
  t3: string;
  brd: string;
  populaire: boolean;
}) {
  const [tab, setTab] = useState<"avantages" | "limites">("avantages");
  const faits = offre.faits || [];
  const avantages = offre.avantages || [];
  const limites = offre.limites || [];
  const hasProsCons = avantages.length > 0 || limites.length > 0;
  const descriptionLines = offre.description_longue.split("\n").map(l => l.trim()).filter(Boolean);
  const nbAvis = offre.institutions?.nb_avis || 0;
  const moyenneAvis = offre.institutions?.moyenne_avis || 0;
  const hasAvis = nbAvis > 0;

  return (
    <>
      <main style={{ flex: 1, overflowY: "auto", padding: "16px 20px 16px", width: "100%", maxWidth: "640px", margin: "0 auto", boxSizing: "border-box" }}>
          {/* Photo de l'offre — retour Bryan 04/08/2026 : sans image
              réelle, l'aperçu reste toujours générique peu importe le
              soin apporté au reste ; absente si l'institution n'a rien
              uploadé (aucune régression pour les offres existantes). */}
          {offre.image_url && (
            <div style={{ width: "100%", height: "180px", borderRadius: "16px", overflow: "hidden", marginBottom: "14px" }}>
              <img src={offre.image_url} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }}/>
            </div>
          )}
          {/* Genre d'offre — badge coloré façon app US */}
          {OFFRE_GENRE_COULEURS[offre.genre as OffreGenre] && (
            <div style={{ marginBottom: "12px" }}>
              <span style={{ display: "inline-block", background: OFFRE_GENRE_COULEURS[offre.genre as OffreGenre].bg, color: OFFRE_GENRE_COULEURS[offre.genre as OffreGenre].texte, fontSize: "10.5px", fontWeight: 800, padding: "4px 11px", borderRadius: "20px", textTransform: "uppercase", letterSpacing: "0.3px" }}>
                {OFFRE_GENRE_LABELS[offre.genre as OffreGenre] || offre.genre}
              </span>
            </div>
          )}
          {/* En-tête partenaire */}
          <div style={{ display: "flex", alignItems: "center", gap: "12px", marginBottom: "18px" }}>
            <div style={{ width: "48px", height: "48px", borderRadius: "13px", flexShrink: 0, overflow: "hidden", background: isDark ? "rgba(245,166,35,0.08)" : "rgba(245,166,35,0.1)", border: "1px solid rgba(245,166,35,0.2)", display: "flex", alignItems: "center", justifyContent: "center" }}>
              {offre.partenaire_logo ? (
                <img src={offre.partenaire_logo} alt={offre.partenaire_nom} style={{ width: "100%", height: "100%", objectFit: "cover" }}/>
              ) : (
                <span style={{ color: "#F5A623", fontWeight: 900, fontSize: "16px" }}>{offre.partenaire_nom.slice(0, 2).toUpperCase()}</span>
              )}
            </div>
            <div style={{ minWidth: 0 }}>
              <div style={{ display: "flex", alignItems: "center", gap: "6px" }}>
                <span style={{ color: t1, fontSize: "13px", fontWeight: 800 }}>{offre.partenaire_nom}</span>
                {hasAvis && (
                  <span style={{ display: "inline-flex", alignItems: "center", gap: "3px", color: t2, fontSize: "12px", fontWeight: 700 }}>
                    <span style={{ color: "#F5A623" }}>★</span>{moyenneAvis.toFixed(1)}
                    <span style={{ color: t3 }}>({nbAvis} avis)</span>
                  </span>
                )}
              </div>
              <div style={{ color: t1, fontSize: "19px", fontWeight: 900, lineHeight: 1.2, letterSpacing: "-0.3px", marginTop: "2px" }}>{offre.titre}</div>
            </div>
          </div>

          {/* Carte de faits */}
          <div style={{ background: isDark ? "rgba(255,255,255,0.03)" : "rgba(0,0,0,0.02)", border: `1px solid ${brd}`, borderRadius: "16px", padding: "16px", marginBottom: "14px" }}>
            <div style={{ color: t2, fontSize: "13px", lineHeight: 1.6 }}>{offre.description_courte}</div>
            {faits.length > 0 && (
              <>
                <div style={{ height: "1px", background: brd, margin: "14px 0 12px" }}/>
                <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
                  {faits.map((f, i) => (
                    <div key={i} style={{ display: "flex", justifyContent: "space-between", gap: "10px" }}>
                      <span style={{ color: t2, fontSize: "13px" }}>{f.label}</span>
                      <span style={{ color: t1, fontSize: "13px", fontWeight: 800 }}>{f.valeur}</span>
                    </div>
                  ))}
                </div>
              </>
            )}
          </div>

          {/* Preuve sociale — badge qualitatif plutôt que le nombre brut de
              clics (retour Bryan 26/07/2026) : "populaire" reflète le
              classement réel de l'offre parmi les plus consultées (même
              critère que la section "Offres populaires" du feed), jamais un
              chiffre inventé. */}
          {populaire && (
            <div style={{ display: "inline-flex", alignItems: "center", gap: "5px", background: isDark ? "rgba(245,166,35,0.1)" : "rgba(245,166,35,0.1)", color: "#F5A623", fontSize: "11px", fontWeight: 800, padding: "6px 12px", borderRadius: "20px", marginBottom: "14px" }}>
              <svg width="12" height="12" viewBox="0 0 24 24" fill="#F5A623"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>
              Offre populaire
            </div>
          )}

          {/* Onglets Avantages / Limites */}
          {hasProsCons && (
            <div style={{ marginBottom: "16px" }}>
              <div style={{ display: "flex", borderBottom: `1px solid ${brd}`, marginBottom: "12px" }}>
                {(["avantages", "limites"] as const).map(k => (
                  (k === "avantages" ? avantages.length > 0 : limites.length > 0) && (
                    <button
                      key={k}
                      onClick={() => setTab(k)}
                      className="tap"
                      style={{
                        flex: 1, padding: "10px 0", background: "none", border: "none",
                        borderBottom: tab === k ? "2px solid #F5A623" : "2px solid transparent",
                        color: tab === k ? t1 : t2, fontWeight: tab === k ? 800 : 600, fontSize: "13.5px", cursor: "pointer",
                      }}
                    >
                      {k === "avantages" ? "Avantages" : "Limites"}
                    </button>
                  )
                ))}
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
                {(tab === "avantages" ? avantages : limites).map((item, i) => (
                  <div key={i} style={{ display: "flex", alignItems: "flex-start", gap: "9px" }}>
                    {tab === "avantages" ? (
                      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#22c55e" strokeWidth="2.5" strokeLinecap="round" style={{ marginTop: "2px", flexShrink: 0 }}><polyline points="20 6 9 17 4 12"/></svg>
                    ) : (
                      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#f59e0b" strokeWidth="2.2" strokeLinecap="round" style={{ marginTop: "2px", flexShrink: 0 }}><path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>
                    )}
                    <span style={{ color: t2, fontSize: "13px", lineHeight: 1.5 }}>{item}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Description de l'offre */}
          <div style={{ marginBottom: "14px" }}>
            <div style={{ color: t1, fontSize: "13.5px", fontWeight: 800, marginBottom: "8px" }}>Description de l&apos;offre</div>
            <div style={{ display: "flex", flexDirection: "column", gap: "6px" }}>
              {descriptionLines.map((line, i) => (
                <div key={i} style={{ display: "flex", gap: "8px" }}>
                  <span style={{ color: "#F5A623" }}>•</span>
                  <span style={{ color: t2, fontSize: "13px", lineHeight: 1.6 }}>{line}</span>
                </div>
              ))}
            </div>
          </div>

          {offre.date_expiration && (
            <div style={{ color: t2, fontSize: "12px", marginBottom: "10px" }}>
              Offre valable jusqu&apos;au {new Date(offre.date_expiration).toLocaleDateString("fr-FR", { day: "numeric", month: "long", year: "numeric" })}.
            </div>
          )}

          <div style={{ color: t2, fontSize: "11.5px", lineHeight: 1.6 }}>
            Offre vérifiée par Yelen avant publication. En continuant, vous quittez Yelen pour le site de {offre.partenaire_nom}.
          </div>
      </main>

      {/* CTA sticky — ouvre directement /api/offres/[id]/clic dans un nouvel
          onglet (geste utilisateur synchrone, jamais bloqué) ; l'interstitiel
          "Un instant, direction {partenaire}" vit dans cette page de
          destination elle-même, pas ici. */}
      {offre.cta_url && (
        <div style={{ padding: "14px 20px calc(14px + env(safe-area-inset-bottom))", borderTop: `1px solid ${brd}`, background: card, flexShrink: 0 }}>
          <a
            href={`/api/offres/${offre.id}/clic`}
            target="_blank"
            rel="noopener noreferrer"
            className="tap"
            style={{
              display: "flex", alignItems: "center", justifyContent: "center", gap: "8px",
              width: "100%", padding: "14px", borderRadius: "14px", textDecoration: "none", boxSizing: "border-box",
              background: "linear-gradient(135deg,#F5A623,#C8940A)", color: "#080812",
              fontWeight: 800, fontSize: "14px", boxShadow: "0 3px 10px rgba(245,166,35,0.2)",
            }}
          >
            {offre.cta_label || "Accéder à l'offre"}
          </a>
        </div>
      )}
    </>
  );
}

export default function OffreFicheOverlay({
  offre, onClose, isDark, bg, card, card2, t1, t2, t3, brd, populaire,
}: {
  offre: Offre;
  onClose: () => void;
  isDark: boolean;
  bg: string;
  card: string;
  card2: string;
  t1: string;
  t2: string;
  t3: string;
  brd: string;
  populaire: boolean;
}) {
  return (
    <div
      className="offre-fiche-overlay"
      style={{
        position: "fixed", inset: 0, zIndex: 1000,
        background: bg, display: "flex", flexDirection: "column",
        animation: "offreFicheFadeIn 0.2s ease",
      }}
    >
      <style>{`@keyframes offreFicheFadeIn{from{opacity:0}to{opacity:1}}`}</style>

      <header style={{ position: "sticky", top: 0, zIndex: 1, background: bg, borderBottom: `1px solid ${brd}`, paddingTop: "env(safe-area-inset-top)", flexShrink: 0 }}>
        <div style={{ padding: "12px 16px", display: "grid", gridTemplateColumns: "1fr auto 1fr", alignItems: "center", gap: "12px" }}>
          <span />
          <div style={{ color: t1, fontSize: "16px", fontWeight: 800, textAlign: "center" }}>Offre</div>
          <button
            onClick={onClose}
            className="tap"
            aria-label="Fermer"
            style={{ justifySelf: "end", width: "36px", height: "36px", borderRadius: "50%", background: card2, border: `1px solid ${brd}`, display: "flex", alignItems: "center", justifyContent: "center", color: t1, cursor: "pointer" }}
          >
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
          </button>
        </div>
      </header>

      <OffreFicheContenu offre={offre} isDark={isDark} card={card} t1={t1} t2={t2} t3={t3} brd={brd} populaire={populaire}/>
    </div>
  );
}

"use client";

// Popup plein écran du profil d'un auteur "Yelen Community" (27/07/2026,
// retour Bryan, référence MoneyLion "BB"/profil). Un seul et même
// composant pour les deux cas : l'auteur d'un autre post, OU le compte
// connecté lui-même (estMoi = post.auteur_id === userId) — jamais un
// second compte, juste une vue différente du MÊME compte Yelen.
// Combine avec Yelen Rewards (retour Bryan) : seulement pour son propre
// profil (solde réel via /api/citoyen/rewards, jamais affiché pour un
// autre auteur — donnée privée).
import { useEffect, useState } from "react";
import Link from "next/link";
import { supabase } from "@/lib/supabase";
import { YelenLoader } from "@/components/YelenLoader";
import { Avatar, BadgeVerifie, formatDateFr, type Post } from "@/components/CommunautePostCard";
import { SECTIONS_INTERET, type CentreInteretId } from "@/lib/centresInteret";

export default function ProfilAuteurOverlay({
  post, estMoi, citoyenInterets, isDark, bg, card, card2, t1, t2, t3, brd, onClose,
}: {
  post: Post;
  estMoi: boolean;
  citoyenInterets: string[];
  isDark: boolean; bg: string; card: string; card2: string; t1: string; t2: string; t3: string; brd: string;
  onClose: () => void;
}) {
  const [publications, setPublications] = useState<Post[] | null>(null);
  const [solde, setSolde] = useState<number | null>(null);

  useEffect(() => {
    let annule = false;
    (async () => {
      const { data } = await supabase
        .from("posts")
        .select("id, auteur_id, author_nom, author_photo_url, author_verifie, author_membre_depuis, contenu, images, nb_partages, created_at")
        .eq("auteur_id", post.auteur_id)
        .eq("statut", "publiee")
        .order("created_at", { ascending: false });
      if (!annule) setPublications((data as Post[]) ?? []);
    })();
    return () => { annule = true; };
  }, [post.auteur_id]);

  useEffect(() => {
    if (!estMoi) return;
    let annule = false;
    (async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session?.access_token) return;
      const res = await fetch("/api/citoyen/rewards", { headers: { Authorization: `Bearer ${session.access_token}` } });
      const j = await res.json().catch(() => null);
      if (!annule && res.ok && typeof j?.solde === "number") setSolde(j.solde);
    })();
    return () => { annule = true; };
  }, [estMoi]);

  const interetsLabels = estMoi
    ? SECTIONS_INTERET.flatMap(s => s.items).filter(i => citoyenInterets.includes(i.id as CentreInteretId)).map(i => i.label)
    : [];

  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 1000, background: bg, display: "flex", flexDirection: "column" }}>
      <style>{`@keyframes profilFicheFadeIn{from{opacity:0}to{opacity:1}}`}</style>
      <header style={{ position: "sticky", top: 0, zIndex: 1, background: bg, borderBottom: `1px solid ${brd}`, paddingTop: "env(safe-area-inset-top)", flexShrink: 0 }}>
        <div style={{ padding: "12px 16px", display: "grid", gridTemplateColumns: "1fr auto 1fr", alignItems: "center", gap: "12px" }}>
          <span />
          <div style={{ color: t1, fontSize: "16px", fontWeight: 800, textAlign: "center" }}>Profil</div>
          <button
            onClick={onClose}
            className="tap"
            aria-label="Fermer"
            style={{ justifySelf: "end", width: "36px", height: "36px", borderRadius: "50%", background: card2, border: `1px solid ${brd}`, display: "flex", alignItems: "center", justifyContent: "center", color: t1, cursor: "pointer" }}
          >
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round"><line x1="18" y1="6" x2="6" y2="18" /><line x1="6" y1="6" x2="18" y2="18" /></svg>
          </button>
        </div>
      </header>

      <main style={{ flex: 1, overflowY: "auto", padding: "24px 20px 40px", width: "100%", maxWidth: "560px", margin: "0 auto", boxSizing: "border-box", animation: "profilFicheFadeIn 0.2s ease" }}>
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", textAlign: "center", marginBottom: "24px" }}>
          <Avatar nom={post.author_nom} photo={post.author_photo_url} taille={88} />
          <div style={{ display: "flex", alignItems: "center", gap: "8px", marginTop: "14px" }}>
            <span style={{ color: t1, fontSize: "19px", fontWeight: 900 }}>{post.author_nom}</span>
            {post.author_verifie && <BadgeVerifie />}
          </div>
          <div style={{ color: t2, fontSize: "12.5px", marginTop: "4px" }}>Membre de Yelen depuis {formatDateFr(post.author_membre_depuis)}</div>
        </div>

        {estMoi && (
          <Link
            href="/menu/recompenses"
            className="tap"
            style={{ display: "flex", alignItems: "center", gap: "12px", background: isDark ? "linear-gradient(135deg,#2B2560,#17171C)" : "linear-gradient(135deg,#FFE9BE,#F5A623)", borderRadius: "16px", padding: "16px", marginBottom: "20px", textDecoration: "none" }}
          >
            <div style={{ width: "40px", height: "40px", borderRadius: "50%", background: isDark ? "rgba(245,166,35,0.18)" : "rgba(255,255,255,0.55)", flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
              <svg width="20" height="20" viewBox="0 0 24 24" fill={isDark ? "#F5A623" : "#5C3D00"}><path d="M12 3c.8 4.4 2.8 6.4 7 7-4.2.8-6.2 2.8-7 7-.8-4.2-2.8-6.2-7-7 4.2-.6 6.2-2.6 7-7z" /></svg>
            </div>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ color: isDark ? "#fff" : "#1C1300", fontSize: "13.5px", fontWeight: 900 }}>Yelen Rewards</div>
              <div style={{ color: isDark ? "rgba(255,255,255,0.7)" : "rgba(28,19,0,0.65)", fontSize: "11.5px" }}>
                {solde === null ? "Voir mes récompenses" : `${solde.toLocaleString("fr-FR")} points — voir tout`}
              </div>
            </div>
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke={isDark ? "#FFC65C" : "#5C3D00"} strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><path d="m9 18 6-6-6-6" /></svg>
          </Link>
        )}

        {estMoi && interetsLabels.length > 0 && (
          <div style={{ marginBottom: "24px" }}>
            <div style={{ color: t2, fontSize: "10.5px", fontWeight: 800, textTransform: "uppercase", letterSpacing: "0.4px", marginBottom: "10px" }}>Centres d&apos;intérêt</div>
            <div style={{ display: "flex", flexWrap: "wrap", gap: "8px" }}>
              {interetsLabels.map(l => (
                <span key={l} style={{ background: card, border: `1px solid ${brd}`, borderRadius: "20px", padding: "6px 12px", color: t1, fontSize: "12px", fontWeight: 700 }}>{l}</span>
              ))}
            </div>
          </div>
        )}

        <div>
          <div style={{ color: t2, fontSize: "10.5px", fontWeight: 800, textTransform: "uppercase", letterSpacing: "0.4px", marginBottom: "10px" }}>Publications</div>
          {publications === null ? (
            <div style={{ display: "flex", justifyContent: "center", padding: "20px" }}><YelenLoader size={20} color={t2} /></div>
          ) : publications.length === 0 ? (
            <div style={{ color: t3, fontSize: "12.5px", textAlign: "center", padding: "20px" }}>Aucune publication pour l&apos;instant.</div>
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
              {publications.map(p => (
                <div key={p.id} style={{ background: card, border: `1px solid ${brd}`, borderRadius: "14px", padding: "14px" }}>
                  <div style={{ color: t2, fontSize: "11px", marginBottom: "6px" }}>{formatDateFr(p.created_at)}</div>
                  {p.contenu && <div style={{ color: t1, fontSize: "13px", lineHeight: 1.5, whiteSpace: "pre-wrap" }}>{p.contenu}</div>}
                  {p.images && p.images.length > 0 && (
                    <div style={{ display: "flex", gap: "6px", marginTop: "8px", overflowX: "auto" }}>
                      {p.images.map((url, i) => (
                        <img key={i} src={url} alt="" style={{ width: "64px", height: "64px", borderRadius: "8px", objectFit: "cover", flexShrink: 0 }} />
                      ))}
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      </main>
    </div>
  );
}

